// The app's icon mark -- the actual approved badge image (navy circle,
// coral ring, cream heart), embedded as a data URI. Replaces both the
// generic lucide PawPrint icon and an earlier hand-built SVG approximation.
// Unlike those, this is a fixed multi-color image, not a recolorable line
// icon -- the "color" prop is accepted (so every existing call site that
// passed one still works unchanged) but has no effect, since a raster image
// can't be recolored the way an SVG path could. Sized via "size" as both
// width and height, since the badge is square/circular.
const HEARTMARK_BADGE_SRC = "data:image/png;base64,";

function HeartMark({ size = 24, color }) {
  return (
    <img
      src={HEARTMARK_BADGE_SRC}
      alt=""
      style={{ width: size, height: size, display: "inline-block", objectFit: "contain" }}
    />
  );
}

// ---------------------------------------------------------------------------
// Real backend connection for the core case/sighting flow. Only reachable
// once you're actually running this outside Claude's chat preview -- the
// preview sandbox can't reach localhost. Once wrapped with Capacitor (or
// just running via `npm run dev` in a browser) with the backend running
// alongside it, this works for real -- see amareunited-backend's README.
// Change API_BASE if the backend is deployed somewhere other than your own
// machine.
// ---------------------------------------------------------------------------
const API_BASE = "http://localhost:4000";

async function apiFetch(path, options) {
  let res;
  try {
    res = await fetch(`${API_BASE}${path}`, {
      headers: { "Content-Type": "application/json" },
      ...options,
    });
  } catch {
    throw new Error(
      `Can't reach the REunited backend at ${API_BASE}. Make sure it's running (npm run dev in amareunited-backend).`
    );
  }
  let body = null;
  try {
    body = await res.json();
  } catch {
    // no JSON body -- fine for some responses
  }
  if (!res.ok) {
    const reason = (body && (body.reason || body.error)) || `request failed (${res.status})`;
    const err = new Error(reason);
    err.status = res.status;
    throw err;
  }
  return body;
}

