// e.g. "Sep 3, 2026" -- used for the lost/found dates on Reunion Stories.
function formatDateLabel(date) {
  return date.toLocaleDateString(undefined, { month: "short", day: "numeric", year: "numeric" });
}

// Computes a human age label from a stored birthday, so age stays accurate
// over time instead of being a static string someone typed once.
function calculateAge(birthday) {
  if (!birthday) return null;
  const birth = new Date(birthday);
  const now = new Date();
  let years = now.getFullYear() - birth.getFullYear();
  let months = now.getMonth() - birth.getMonth();
  if (now.getDate() < birth.getDate()) months -= 1;
  if (months < 0) {
    years -= 1;
    months += 12;
  }
  if (years < 1) {
    return months <= 0 ? "Less than a month old" : `${months} month${months === 1 ? "" : "s"} old`;
  }
  return `${years} year${years === 1 ? "" : "s"} old`;
}

