function MainApp({ initialProfile, signupRank, messagesByThread, setMessagesByThread, onDeleteAccount }) {
  // home | details | review | active | trail | reportSighting | pendingSighting | reunite | reunited
  const [screen, setScreen] = useState("home");
  const [selectedPetId, setSelectedPetId] = useState(null);
  const [pin, setPin] = useState(null); // { xPct, yPct }
  const [timeLabel, setTimeLabel] = useState(null);
  const [customTime, setCustomTime] = useState("");
  const [showCustomTime, setShowCustomTime] = useState(false);
  const [radiusKm, setRadiusKm] = useState(3);
  const [activeCases, setActiveCases] = useState({}); // petId -> true
  const [caseDates, setCaseDates] = useState({}); // petId -> { lostAt: Date, foundAt: Date | null }
  // Real backend integration for the core flow (case create/activate,
  // sighting submit + trust-pipeline scoring, reunite). Only covers your
  // own pets going through the normal Report Missing -> Activate ->
  // ReportSightingScreen path -- Found Pet matching, Admin data, Messaging,
  // Reunion Stories, and Founding Member rank all stay frontend-only mock,
  // since the backend has no concept of any of those yet.
  const [backendCaseIdByPet, setBackendCaseIdByPet] = useState({});
  const [apiError, setApiError] = useState(null);
  const [reunitedCases, setReunitedCases] = useState({}); // petId -> { heroName, message }
  const [sightingsByPet, setSightingsByPet] = useState(INITIAL_SIGHTINGS);
  const [heroSelection, setHeroSelection] = useState(null);
  const [thankYouMessage, setThankYouMessage] = useState("");
  const [posts, setPosts] = useState(INITIAL_POSTS);
  const [pets, setPets] = useState(PETS_SEED);
  const [ownerAlert, setOwnerAlert] = useState(null); // { petId, petName, species, distanceLabel, timeLabel } | null

  // Profile stats. "My Pets" and "My Reports" are computed live from real
  // app state below. Sightings-submitted starts with some seed history (so
  // the profile isn't empty on first look) and increments with real
  // activity. Hero Reunions and thank-you messages are static mock data --
  // there's no in-app mechanic yet for the current user to actually receive
  // a Hero Badge or thank-you (only to award one to someone else), since
  // that would require a second account's perspective.
  const [sightingsSubmittedCount, setSightingsSubmittedCount] = useState(8);
  const [heroReunionsCount] = useState(3);
  const [thankYouMessagesReceived] = useState([
    { id: "ty1", petName: "Max", message: "Thank you for helping us find Max!" },
  ]);

  // User profile -- name/contact/address/emergency contact, now collected
  // directly during account creation (see ProfileDetailsStep in Onboarding)
  // rather than left for the user to fill in later. Falls back to sensible
  // blanks/defaults only if onboarding data is somehow missing.
  const [userProfile, setUserProfile] = useState(() => ({
    fullName: initialProfile?.fullName || "",
    phone: initialProfile?.contactMethod === "phone" ? initialProfile.contact : "",
    email: initialProfile?.contactMethod === "email" ? initialProfile.contact : "",
    address: initialProfile?.address || "",
    emergencyContactName: initialProfile?.emergencyContactName || "",
    emergencyContactPhone: initialProfile?.emergencyContactPhone || "",
  }));

  const [selectedStoryId, setSelectedStoryId] = useState(null);
  const [storyOrigin, setStoryOrigin] = useState("profile"); // where "back" from a story goes
  const [reunionStories, setReunionStories] = useState(INITIAL_REUNION_STORIES);
  const [shareAsStory, setShareAsStory] = useState(false);
  const [foundPetCapture, setFoundPetCapture] = useState(null); // { species, primaryColor, photoColor, locationLabel, captureLat, captureLng, gpsAccuracyMeters }
  const [foundPetsBoard, setFoundPetsBoard] = useState(INITIAL_FOUND_PETS_BOARD);
  const [messageThreadSubject, setMessageThreadSubject] = useState(null); // { id, title, subtitle, origin }
  // messagesByThread/setMessagesByThread now come from App as props -- lifted
  // up so the admin-feedback thread survives switching to the Admin view
  // (MainApp fully unmounts on that switch, which would otherwise discard it).
  const [profileOrigin, setProfileOrigin] = useState("home"); // where "back" from the profile screen goes
  const mapRef = useRef(null);

  // Tab bar (My Pets / Community) only shows on the two top-level screens;
  // every other screen is a focused flow, same pattern as the rest of the app.
  const TOP_LEVEL_SCREENS = ["home", "feed", "alerts", "profile"];

  // Community alert "pets" aren't in your own pets list (they belong to
  // other people), but the report-a-sighting flow needs to resolve them the
  // same way, since it reuses the same screens for "your own case" and
  // "helping a neighbor."
  const selectedPet = [...pets, ...COMMUNITY_ALERTS].find((p) => p.id === selectedPetId) || null;
  const isOwnPet = selectedPetId ? pets.some((p) => p.id === selectedPetId) : false;
  const activePets = pets.filter((p) => activeCases[p.id] && !reunitedCases[p.id]);

  function startReport(petId) {
    setSelectedPetId(petId);
    setPin(null);
    setTimeLabel(null);
    setShowCustomTime(false);
    setCustomTime("");
    setRadiusKm(3);
    setScreen("details");
  }

  function handleMapClick(e) {
    const rect = mapRef.current.getBoundingClientRect();
    const xPct = ((e.clientX - rect.left) / rect.width) * 100;
    const yPct = ((e.clientY - rect.top) / rect.height) * 100;
    setPin({ xPct, yPct });
  }

  function useCurrentLocation() {
    setPin({ xPct: 50, yPct: 50, isCurrent: true });
  }

  function rawCoordsForPin(p) {
    if (!p) return null;
    return {
      lat: 14.676 + (50 - p.yPct) * 0.0006,
      lng: 121.044 + (p.xPct - 50) * 0.0006,
    };
  }

  function coordsForPin(p) {
    const c = rawCoordsForPin(p);
    return c ? `${c.lat.toFixed(4)}, ${c.lng.toFixed(4)}` : null;
  }

  // Converts a TIME_CHIPS label into an actual Date by subtracting a rough
  // offset from now -- these are relative labels ("15 minutes ago"), not
  // real timestamps, so this is an approximation, not a precise capture.
  function dateFromRelativeLabel(label) {
    const minutesAgo = { "Just now": 1, "15 minutes ago": 15, "1 hour ago": 60, "This morning": 240 }[label] ?? 5;
    return new Date(Date.now() - minutesAgo * 60000);
  }

  async function activateCase() {
    setActiveCases((prev) => ({ ...prev, [selectedPetId]: true }));
    const lostAt = showCustomTime && customTime ? new Date(customTime) : dateFromRelativeLabel(timeLabel);
    setCaseDates((prev) => ({ ...prev, [selectedPetId]: { lostAt, foundAt: null } }));
    setScreen("active");

    // Real backend sync, best-effort: the local UI above already reflects
    // the activation regardless of whether this succeeds, so a backend
    // outage doesn't block the owner from using the app -- it just means
    // sightings for this case won't get real trust-pipeline scoring until
    // the backend is reachable (see submitSighting).
    try {
      const coords = rawCoordsForPin(pin);
      const created = await apiFetch("/cases", {
        method: "POST",
        body: JSON.stringify({ ownerId: "owner-demo", petId: selectedPetId }),
      });
      await apiFetch(`/cases/${created.id}/activate`, {
        method: "POST",
        body: JSON.stringify({
          lastKnownLat: coords.lat,
          lastKnownLng: coords.lng,
          lastKnownAt: lostAt.toISOString(),
        }),
      });
      setBackendCaseIdByPet((prev) => ({ ...prev, [selectedPetId]: created.id }));
      setApiError(null);
    } catch (err) {
      setApiError(err.message);
    }
  }

  function openTrail(petId) {
    setSelectedPetId(petId);
    setScreen("trail");
  }

  function openReportSighting(petId) {
    setSelectedPetId(petId);
    setScreen("reportSighting");
  }

  async function submitSighting(newSighting) {
    const backendCaseId = backendCaseIdByPet[selectedPetId];
    let finalSighting = newSighting;

    // Resolved BEFORE navigating to PendingSightingScreen, deliberately --
    // if we set backendTracked after the screen has already mounted and
    // started its local simulated pipeline, the two could race (simulated
    // and real results both trying to finalize the same sighting). Backend
    // calls here are to a local/nearby service, so this adds negligible
    // delay in the common case.
    if (backendCaseId && newSighting.captureLat) {
      try {
        const created = await apiFetch("/sightings", {
          method: "POST",
          body: JSON.stringify({
            caseId: backendCaseId,
            reporterId: newSighting.reporterName,
            captureLat: newSighting.captureLat,
            captureLng: newSighting.captureLng,
            gpsAccuracyMeters: newSighting.gpsAccuracyMeters,
            capturedAt: new Date().toISOString(),
            // Demo transport: a unique string per photo standing in for
            // real image bytes, so repeat submissions don't hash
            // identically and trip the backend's duplicate-image check.
            imageBase64: `${newSighting.id}-0-${Math.random().toString(36).slice(2)}`,
            additionalImageBase64: (newSighting.photos || []).slice(1).map(
              (_, i) => `${newSighting.id}-${i + 1}-${Math.random().toString(36).slice(2)}`
            ),
            comment: newSighting.comment || undefined,
          }),
        });
        // Real backend id + flag so PendingSightingScreen polls for real
        // signals. Local-only display fields (photos, reporterName,
        // distanceLabel) are kept from the original entry.
        finalSighting = { ...newSighting, id: created.id, backendTracked: true };
        setApiError(null);
      } catch (err) {
        setApiError(err.message);
        // finalSighting stays as the original -- PendingSightingScreen
        // falls back to the local simulated pipeline for it.
      }
    }

    setSightingsByPet((prev) => ({
      ...prev,
      [selectedPetId]: [...(prev[selectedPetId] || []), finalSighting],
    }));
    setSightingsSubmittedCount((prev) => prev + 1);
    setScreen("pendingSighting");
  }

  function openFoundPet() {
    setFoundPetCapture(null);
    setScreen("foundPet");
  }

  function submitFoundPetCapture(capture) {
    setFoundPetCapture(capture);
    setScreen("foundPetMatches");
  }

  // A confirmed match skips the scoring pipeline entirely -- the finder has
  // physical custody of the pet and explicitly matched it to this case,
  // which is stronger evidence than any photo-based sighting the pipeline
  // was built to evaluate. It's recorded as CONFIRMED immediately, and the
  // owner is alerted right away rather than waiting on staged scoring.
  function confirmFoundPetMatch(petId) {
    setSelectedPetId(petId);
    const reporterName = MOCK_REPORTER_POOL[Math.floor(Math.random() * MOCK_REPORTER_POOL.length)];
    const distanceLabel = `${(0.2 + Math.random() * 1.5).toFixed(1)} km away`;
    const sighting = {
      id: `s-${Date.now()}`,
      reporterName,
      distanceLabel,
      timeLabel: "just now",
      confidence: "CONFIRMED",
      signals: ["Reporter has physical custody of this pet — matched directly to your missing-pet report"],
      origin: "foundPet",
      photos: foundPetCapture?.photos || [],
      photoColor: foundPetCapture?.photos?.[0],
      comment: foundPetCapture?.comment || "",
    };
    setSightingsByPet((prev) => ({
      ...prev,
      [petId]: [...(prev[petId] || []), sighting],
    }));
    setSightingsSubmittedCount((prev) => prev + 1);

    const isOwnActivePet = pets.some((p) => p.id === petId) && activeCases[petId];
    if (isOwnActivePet) {
      const pet = pets.find((p) => p.id === petId);
      setOwnerAlert({
        petId,
        petName: pet?.name,
        species: pet?.species,
        distanceLabel,
        timeLabel: "just now",
        origin: "foundPet",
      });
    }

    setScreen("foundPetMatchConfirmed");
  }

  function reportFoundPetNoMatch() {
    setFoundPetsBoard((prev) => [
      {
        id: `found-${Date.now()}`,
        species: foundPetCapture.species,
        primaryColor: foundPetCapture.primaryColor || "Not noted",
        comment: foundPetCapture.comment || "",
        locationLabel: foundPetCapture.locationLabel,
        timeLabel: "just now",
        finderName: "You",
        photos: foundPetCapture.photos || [],
        photoColor: foundPetCapture.photos?.[0],
      },
      ...prev,
    ]);
    setScreen("foundPetPosted");
  }

  function openReunionStory(storyId, origin) {
    setSelectedStoryId(storyId);
    setStoryOrigin(origin);
    setScreen("reunionStory");
  }

  function finalizeSighting(sightingId, finalConfidence, finalSignals) {
    setSightingsByPet((prev) => ({
      ...prev,
      [selectedPetId]: prev[selectedPetId].map((s) =>
        s.id === sightingId ? { ...s, confidence: finalConfidence, signals: finalSignals } : s
      ),
    }));

    // Owner alert: fires when a sighting on one of YOUR active pets crosses
    // a credible confidence level. Mirrors the backend pipeline's own
    // MEDIUM+ notification threshold (see notify.ts) -- a single early
    // signal shouldn't be enough to alert the owner, only a scored,
    // credible sighting.
    const isOwnActivePet = pets.some((p) => p.id === selectedPetId) && activeCases[selectedPetId];
    if (isOwnActivePet && (finalConfidence === "MEDIUM" || finalConfidence === "HIGH")) {
      const pet = pets.find((p) => p.id === selectedPetId);
      const sighting = (sightingsByPet[selectedPetId] || []).find((s) => s.id === sightingId);
      setOwnerAlert({
        petId: selectedPetId,
        petName: pet?.name,
        species: pet?.species,
        distanceLabel: sighting?.distanceLabel || "nearby",
        timeLabel: sighting?.timeLabel || "just now",
      });
    }
  }

  function openReunite(petId) {
    setSelectedPetId(petId);
    setHeroSelection(null);
    setThankYouMessage("");
    setShareAsStory(false);
    setScreen("reunite");
  }

  function confirmReunite() {
    const hero = (sightingsByPet[selectedPetId] || []).find((s) => s.id === heroSelection);
    setReunitedCases((prev) => ({
      ...prev,
      [selectedPetId]: { heroName: hero ? hero.reporterName : null, message: thankYouMessage },
    }));

    const foundAt = new Date();
    const existingDates = caseDates[selectedPetId];
    setCaseDates((prev) => ({
      ...prev,
      [selectedPetId]: { lostAt: existingDates?.lostAt || foundAt, foundAt },
    }));

    // Opt-in public sharing: only when the owner explicitly chose "Share
    // Publicly" (not the default) AND there's a hero + message worth
    // sharing -- an empty or private thank-you never becomes a public story.
    if (shareAsStory && hero && thankYouMessage.trim()) {
      const pet = pets.find((p) => p.id === selectedPetId);
      setReunionStories((prev) => [
        {
          id: `rs-${Date.now()}`,
          petName: pet?.name,
          ownerName: "You",
          heroName: hero.reporterName,
          message: thankYouMessage.trim(),
          photoColor: pet?.color || "#E2572B",
          timeLabel: "just now",
          lostDateLabel: existingDates?.lostAt ? formatDateLabel(existingDates.lostAt) : null,
          foundDateLabel: formatDateLabel(foundAt),
        },
        ...prev,
      ]);
    }
    setScreen("reunited");
  }

  function addPost(newPost) {
    setPosts((prev) => [newPost, ...prev]);
    setScreen("feed");
  }

  function likePost(postId) {
    setPosts((prev) => prev.map((p) => (p.id === postId ? { ...p, likes: p.likes + 1 } : p)));
  }

  function addPet(newPet) {
    setPets((prev) => [...prev, newPet]);
    setScreen("home");
  }

  // Generic message thread -- works for a sighting reporter (from a Trail)
  // or a Found Pets Board finder (from Alerts), since both are just "a
  // person you might need to coordinate with," not something tied to a
  // specific pet's case data.
  function openMessageThread(subject) {
    setMessageThreadSubject(subject);
    setScreen("messageThread");
  }

  function openPetProfile(petId, origin) {
    setSelectedPetId(petId);
    setProfileOrigin(origin);
    setScreen("petProfile");
  }

  function sendMessage(threadId, text) {
    const outgoing = { sender: "you", text, timeLabel: "just now" };
    setMessagesByThread((prev) => ({
      ...prev,
      [threadId]: [...(prev[threadId] || []), outgoing],
    }));
    // Simulated reply for sighting/found-pet threads only, since there's no
    // real other person on the other end of those in this demo. The
    // admin-feedback thread does NOT get an auto-reply -- Amari (the admin)
    // now sends real replies from the Admin dashboard instead, so an instant
    // canned response would be misleading and would clash with a genuine
    // reply arriving later.
    if (threadId === ADMIN_FEEDBACK_THREAD_ID) return;
    setTimeout(() => {
      const reply = {
        sender: "them",
        text: MOCK_REPLY_POOL[Math.floor(Math.random() * MOCK_REPLY_POOL.length)],
        timeLabel: "just now",
      };
      setMessagesByThread((prev) => ({
        ...prev,
        [threadId]: [...(prev[threadId] || []), reply],
      }));
    }, 1100);
  }

  const canContinueDetails = pin && (timeLabel || (showCustomTime && customTime));
  const showTabBar = TOP_LEVEL_SCREENS.includes(screen);

  // Android hardware/gesture back button. Deliberately NOT a static
  // `import { App } from '@capacitor/app'` -- that package isn't part of
  // this project yet (it only exists once this is actually wrapped with
  // Capacitor), and a static import of a missing package would break the
  // build for anyone just running this as a plain web app or viewing it in
  // a browser/preview. Instead this reads window.Capacitor.Plugins.App at
  // runtime, which Capacitor injects automatically in a real native build
  // and which simply doesn't exist anywhere else -- so this is a genuine
  // no-op everywhere except inside an actual Capacitor Android app.
  // Without this, Android's back button has no in-app handler at all and
  // falls through to the OS default, which typically just closes the app
  // instead of navigating your screen stack backward -- exactly the gap
  // flagged in the Android guidelines review.
  useEffect(() => {
    const capacitorApp = window.Capacitor?.Plugins?.App;
    if (!capacitorApp) return;

    const listener = capacitorApp.addListener("backButton", () => {
      if (TOP_LEVEL_SCREENS.includes(screen)) {
        // Standard Android convention: back on a root/tab screen exits the
        // app rather than navigating -- it doesn't "go back" from Home.
        capacitorApp.exitApp();
      } else {
        // Not a true per-screen back stack (that would need every setScreen
        // call in this component threaded through a history array, a much
        // larger refactor) -- but returning to Home is a safe, correct "up"
        // destination from any sub-screen, and matches what several of this
        // app's own in-screen back buttons already do.
        setScreen("home");
      }
    });

    return () => {
      listener.then((l) => l.remove()).catch(() => {});
    };
  }, [screen]);

  return (
    <>
      {ownerAlert && (
        <OwnerAlertBanner
          alert={ownerAlert}
          onDismiss={() => setOwnerAlert(null)}
          onViewSighting={() => {
            setOwnerAlert(null);
            openTrail(ownerAlert.petId);
          }}
        />
      )}
      {screen === "home" && (
        <HomeScreen
          pets={pets}
          activeCases={activeCases}
          reunitedCases={reunitedCases}
          onReport={startReport}
          onOpenTrail={openTrail}
          onAddPet={() => setScreen("addPet")}
          onOpenProfile={(petId) => openPetProfile(petId, "home")}
        />
      )}
      {screen === "addPet" && (
        <AddPetScreen onBack={() => setScreen("home")} onSave={addPet} />
      )}
      {screen === "alerts" && (
        <AlertsScreen
          myActivePets={activePets}
          communityAlerts={COMMUNITY_ALERTS}
          foundPetsBoard={foundPetsBoard}
          sightingsByPet={sightingsByPet}
          onOpenTrail={openTrail}
          onReportSighting={openReportSighting}
          onOpenProfile={(petId) => openPetProfile(petId, "alerts")}
          onFoundPet={openFoundPet}
          onMessageFinder={(f) =>
            openMessageThread({
              id: f.id,
              title: f.finderName,
              subtitle: `About the pet they found — ${f.species} · ${f.locationLabel}`,
              origin: "alerts",
            })
          }
        />
      )}
      {screen === "foundPet" && (
        <FoundPetScreen onBack={() => setScreen("alerts")} onSubmit={submitFoundPetCapture} />
      )}
      {screen === "foundPetMatches" && foundPetCapture && (
        <FoundPetMatchesScreen
          capture={foundPetCapture}
          candidates={[...activePets, ...COMMUNITY_ALERTS].filter((p) => p.species === foundPetCapture.species)}
          onBack={() => setScreen("foundPet")}
          onConfirmMatch={confirmFoundPetMatch}
          onNoMatch={reportFoundPetNoMatch}
        />
      )}
      {screen === "foundPetPosted" && (
        <FoundPetPostedScreen onDone={() => setScreen("alerts")} />
      )}
      {screen === "foundPetMatchConfirmed" && selectedPet && (
        <FoundPetMatchConfirmedScreen
          pet={selectedPet}
          onDone={() => setScreen(isOwnPet ? "trail" : "alerts")}
        />
      )}
      {screen === "profile" && (
        <ProfileScreen
          userProfile={userProfile}
          myPetsCount={pets.length}
          myReportsCount={Object.keys(activeCases).length}
          sightingsCount={sightingsSubmittedCount}
          heroReunionsCount={heroReunionsCount}
          thankYouMessages={thankYouMessagesReceived}
          signupRank={signupRank}
          onViewReunionStory={(id) => openReunionStory(id, "profile")}
          onEditProfile={() => setScreen("profileEdit")}
          onViewAmariMessage={() => setScreen("amariMessage")}
          onMessageAmari={() =>
            openMessageThread({
              id: ADMIN_FEEDBACK_THREAD_ID,
              title: "Amari",
              subtitle: "Feedback for the REunited team",
              origin: "profile",
            })
          }
          onOpenSettings={() => setScreen("settings")}
        />
      )}
      {screen === "settings" && (
        <SettingsScreen
          onBack={() => setScreen("profile")}
          onEditProfile={() => setScreen("profileEdit")}
          onChangePassword={() => setScreen("changePassword")}
          onNotificationSettings={() => setScreen("notificationSettings")}
          onPrivacyPolicy={() => setScreen("privacyPolicy")}
          onTerms={() => setScreen("terms")}
          onDeleteAccount={() => setScreen("deleteAccountStep1")}
        />
      )}
      {screen === "privacyPolicy" && (
        <PrivacyPolicyScreen
          onBack={() => setScreen("settings")}
          onContactSupport={() =>
            openMessageThread({
              id: ADMIN_FEEDBACK_THREAD_ID,
              title: "Amari",
              subtitle: "Support question via Privacy Policy",
              origin: "privacyPolicy",
            })
          }
        />
      )}
      {screen === "terms" && (
        <TermsScreen onBack={() => setScreen("settings")} onUnderstand={() => setScreen("settings")} />
      )}
      {screen === "changePassword" && (
        <ChangePasswordScreen onBack={() => setScreen("settings")} />
      )}
      {screen === "notificationSettings" && (
        <NotificationSettingsScreen onBack={() => setScreen("settings")} />
      )}
      {screen === "deleteAccountStep1" && (
        <DeleteAccountStep1Screen
          onBack={() => setScreen("settings")}
          onContinue={() => setScreen("deleteAccountStep2")}
        />
      )}
      {screen === "deleteAccountStep2" && (
        <DeleteAccountStep2Screen
          onBack={() => setScreen("settings")}
          onConfirm={onDeleteAccount}
        />
      )}
      {screen === "amariMessage" && signupRank && (
        <AmariMessageScreen rank={signupRank} onBack={() => setScreen("profile")} />
      )}
      {screen === "profileEdit" && (
        <ProfileEditScreen
          userProfile={userProfile}
          onSave={(updated) => {
            setUserProfile(updated);
            setScreen("profile");
          }}
          onBack={() => setScreen("profile")}
        />
      )}
      {screen === "reunionStory" && (
        <ReunionStoryScreen
          story={[...thankYouMessagesReceived, ...reunionStories].find((m) => m.id === selectedStoryId)}
          onBack={() => setScreen(storyOrigin)}
        />
      )}
      {screen === "petProfile" && selectedPet && (
        <PetProfileScreen
          pet={selectedPet}
          isOwnPet={isOwnPet}
          isActive={isOwnPet && activeCases[selectedPet.id] && !reunitedCases[selectedPet.id]}
          sightingCount={(sightingsByPet[selectedPet.id] || []).length}
          onBack={() => setScreen(profileOrigin)}
          onViewTrail={() => openTrail(selectedPet.id)}
          onReportSighting={() => openReportSighting(selectedPet.id)}
          onReportMissing={() => startReport(selectedPet.id)}
        />
      )}
      {screen === "feed" && (
        <FeedScreen
          posts={posts}
          onLike={likePost}
          onNewPost={() => setScreen("newPost")}
          onAddPet={() => setScreen("addPet")}
          hasPets={pets.length > 0}
          reunionStories={reunionStories}
          onViewReunionStory={(id) => openReunionStory(id, "feed")}
        />
      )}
      {screen === "newPost" && (
        <NewPostScreen pets={pets} onBack={() => setScreen("feed")} onSubmit={addPost} />
      )}
      {screen === "details" && selectedPet && (
        <DetailsScreen
          pet={selectedPet}
          pin={pin}
          mapRef={mapRef}
          onMapClick={handleMapClick}
          onUseCurrentLocation={useCurrentLocation}
          coordsForPin={coordsForPin}
          timeLabel={timeLabel}
          setTimeLabel={setTimeLabel}
          showCustomTime={showCustomTime}
          setShowCustomTime={setShowCustomTime}
          customTime={customTime}
          setCustomTime={setCustomTime}
          canContinue={canContinueDetails}
          onBack={() => setScreen("home")}
          onContinue={() => setScreen("review")}
        />
      )}
      {screen === "review" && selectedPet && (
        <ReviewScreen
          pet={selectedPet}
          coords={coordsForPin(pin)}
          timeLabel={showCustomTime ? customTime : timeLabel}
          radiusKm={radiusKm}
          setRadiusKm={setRadiusKm}
          onBack={() => setScreen("details")}
          onActivate={activateCase}
        />
      )}
      {screen === "active" && selectedPet && (
        <ActiveScreen
          pet={selectedPet}
          radiusKm={radiusKm}
          onDone={() => setScreen("home")}
          onViewTrail={() => openTrail(selectedPet.id)}
        />
      )}
      {screen === "trail" && selectedPet && (
        <TrailScreen
          pet={selectedPet}
          sightings={sightingsByPet[selectedPet.id] || []}
          onBack={() => setScreen("home")}
          onReportSighting={() => openReportSighting(selectedPet.id)}
          onReunite={() => openReunite(selectedPet.id)}
          onMessage={(s) =>
            openMessageThread({
              id: s.id,
              title: s.reporterName,
              subtitle: `About their sighting ${s.distanceLabel} · ${s.timeLabel}`,
              origin: "trail",
            })
          }
        />
      )}
      {screen === "messageThread" && messageThreadSubject && (
        <MessageThreadScreen
          title={messageThreadSubject.title}
          subtitle={messageThreadSubject.subtitle}
          messages={messagesByThread[messageThreadSubject.id] || []}
          onBack={() => setScreen(messageThreadSubject.origin || "home")}
          onSend={(text) => sendMessage(messageThreadSubject.id, text)}
        />
      )}
      {screen === "reportSighting" && selectedPet && (
        <ReportSightingScreen
          pet={selectedPet}
          onBack={() => setScreen(isOwnPet && activeCases[selectedPet.id] ? "trail" : "alerts")}
          onSubmit={submitSighting}
        />
      )}
      {screen === "pendingSighting" && selectedPet && (
        <PendingSightingScreen
          pet={selectedPet}
          sighting={(sightingsByPet[selectedPet.id] || []).slice(-1)[0]}
          onFinalize={finalizeSighting}
          onDone={() => setScreen(isOwnPet ? "trail" : "alerts")}
        />
      )}
      {screen === "reunite" && selectedPet && (
        <ReuniteScreen
          pet={selectedPet}
          sightings={sightingsByPet[selectedPet.id] || []}
          heroSelection={heroSelection}
          setHeroSelection={setHeroSelection}
          thankYouMessage={thankYouMessage}
          setThankYouMessage={setThankYouMessage}
          shareAsStory={shareAsStory}
          setShareAsStory={setShareAsStory}
          onBack={() => setScreen("trail")}
          onConfirm={confirmReunite}
        />
      )}
      {screen === "reunited" && selectedPet && (
        <ReunitedScreen
          pet={selectedPet}
          reunion={reunitedCases[selectedPet.id]}
          onDone={() => setScreen("home")}
        />
      )}
      {showTabBar && <TabBar screen={screen} setScreen={setScreen} />}
    </>
  );
}

function OwnerAlertBanner({ alert, onDismiss, onViewSighting }) {
  const isFoundConfirmed = alert.origin === "foundPet";
  return (
    <div
      className="fixed top-4 inset-x-0 flex justify-center px-4 z-50"
      style={{ pointerEvents: "none" }}
    >
      <div
        className="amr-fade-in amr-panel rounded-lg p-4 w-full max-w-sm shadow-lg"
        style={{ pointerEvents: "auto" }}
      >
        <div className="flex items-start justify-between gap-2 mb-2">
          <div className="font-semibold text-sm">
            {isFoundConfirmed ? `🐾 ${alert.petName} Has Been Found!` : `👀 Possible Sighting of ${alert.petName}`}
          </div>
          <button onClick={onDismiss} aria-label="Dismiss" className="text-lg leading-none" style={{ color: "#6B6459" }}>
            ×
          </button>
        </div>
        <p className="text-sm mb-3" style={{ color: "#6B6459" }}>
          {isFoundConfirmed
            ? `A community member says they currently have ${alert.petName} with them, found ${alert.distanceLabel} from the last-known area.`
            : `A community member reported seeing a ${(alert.species || "pet").toLowerCase()} matching ${alert.petName} ${alert.distanceLabel} from the last-known area.`}
        </p>
        <div className="text-xs space-y-1 mb-3" style={{ color: "#6B6459" }}>
          <div>📷 Photo submitted</div>
          <div>📍 Location captured</div>
          <div>🕐 {alert.timeLabel}</div>
          {isFoundConfirmed && <div>🐾 Physical custody confirmed</div>}
        </div>
        <button onClick={onViewSighting} className="amr-btn-primary w-full py-2 rounded-md text-sm">
          {isFoundConfirmed ? "View & Message Them" : "View Sighting"}
        </button>
      </div>
    </div>
  );
}

function ScreenHeader({ title, onBack }) {
  return (
    <div className="flex items-center gap-3 mb-6">
      {onBack ? (
        <button onClick={onBack} className="p-2.5 -ml-2.5 rounded-full hover:bg-black/5" aria-label="Back">
          <ChevronLeft size={30} />
        </button>
      ) : (
        <HeartMark size={30} />
      )}
      <span className="font-semibold text-lg tracking-tight">{title}</span>
    </div>
  );
}

// The app's wordmark -- the actual approved logo file, embedded as a data
// URI so this stays a single portable file with no external asset
// dependency. Background was made transparent (the original export had a
// solid opaque cream fill) so it sits cleanly on any surface, including the
// dark Admin dashboard header.
const REUNITED_LOGO_SRC = "data:image/png;base64,";

// height-per-size lookup -- images don't respond to Tailwind text-size
// classes the way text did, so each call site's intended size maps to an
// explicit pixel height. Width is auto to preserve the logo's aspect ratio.
const WORDMARK_HEIGHTS = {
  "text-base": 114,
  "text-xl": 150,
  "text-2xl": 186,
  "text-3xl": 240,
};

function Wordmark({ size = "text-2xl" }) {
  const height = WORDMARK_HEIGHTS[size] || 150;
  return (
    <img
      src={REUNITED_LOGO_SRC}
      alt="REunited"
      style={{ maxHeight: `${height}px`, maxWidth: "100%", width: "auto", height: "auto", display: "inline-block" }}
    />
  );
}

function ConfidenceBadge({ level }) {
  const style = CONFIDENCE_STYLE[level] || CONFIDENCE_STYLE.LOW;
  return (
    <span className="text-xs font-semibold px-2 py-1 rounded-full shrink-0" style={{ background: style.bg, color: style.fg }}>
      {style.label}
    </span>
  );
}

function HomeScreen({ pets, activeCases, reunitedCases, onReport, onOpenTrail, onAddPet, onOpenProfile }) {
  return (
    <div>
      <div className="mb-6">
        <Wordmark size="text-2xl" />
      </div>
      <p className="text-sm mb-5" style={{ color: "#6B6459" }}>
        Your pets, safe at home or being searched for.
      </p>
      <div className="flex flex-col gap-3">
        {pets.map((pet) => {
          const isActive = activeCases[pet.id] && !reunitedCases[pet.id];
          const reunion = reunitedCases[pet.id];
          return (
            <div
              key={pet.id}
              onClick={() => onOpenProfile(pet.id)}
              className="amr-panel rounded-lg p-4"
              style={{ cursor: "pointer" }}
            >
              <div className="flex items-center gap-3">
                <div
                  className="w-12 h-12 rounded-full flex items-center justify-center text-white font-semibold text-lg shrink-0"
                  style={{ background: pet.color }}
                >
                  {pet.name[0]}
                </div>
                <div className="flex-1 min-w-0">
                  <div className="font-semibold">{pet.name}</div>
                  <div className="text-xs" style={{ color: "#6B6459" }}>
                    {pet.breed} · {pet.species}
                  </div>
                </div>
                {isActive && (
                  <div className="flex items-center gap-1.5 text-xs font-semibold" style={{ color: "#2F6E62" }}>
                    <span className="w-2 h-2 rounded-full amr-pulse" style={{ background: "#2F6E62" }} />
                    ACTIVE SEARCH
                  </div>
                )}
                {reunion && (
                  <div className="flex items-center gap-1 text-xs font-semibold" style={{ color: "#E2572B" }}>
                    <Heart size={13} fill="#E2572B" /> REUNITED
                  </div>
                )}
              </div>

              {isActive ? (
                <button
                  onClick={(e) => { e.stopPropagation(); onOpenTrail(pet.id); }}
                  className="amr-btn-teal w-full mt-3 py-2.5 rounded-md text-sm"
                >
                  View sighting trail
                </button>
              ) : (
                <button
                  onClick={(e) => { e.stopPropagation(); onReport(pet.id); }}
                  className="amr-btn-primary w-full mt-3 py-2.5 rounded-md text-sm"
                >
                  Report Missing
                </button>
              )}
            </div>
          );
        })}
      </div>

      <button
        onClick={onAddPet}
        className="amr-btn-secondary w-full mt-4 py-2.5 rounded-md text-sm flex items-center justify-center gap-2"
      >
        <Plus size={16} />
        Add Your Pet
      </button>
    </div>
  );
}

const MAX_PET_PHOTOS = 5;

function AddPetScreen({ onBack, onSave }) {
  const [photos, setPhotos] = useState([]); // array of colors, standing in for real photo bytes
  const [name, setName] = useState("");
  const [species, setSpecies] = useState("Dog");
  const [breed, setBreed] = useState("");
  const [sex, setSex] = useState("Female");
  const [birthday, setBirthday] = useState("");
  const [primaryColor, setPrimaryColor] = useState("");
  const [markings, setMarkings] = useState("");
  const [microchipped, setMicrochipped] = useState(null); // "yes" | "no"
  const [microchipNumber, setMicrochipNumber] = useState("");

  function addPhoto() {
    if (photos.length >= MAX_PET_PHOTOS) return;
    const usedColors = new Set(photos);
    const available = PET_AVATAR_COLORS.filter((c) => !usedColors.has(c));
    const nextColor = (available.length > 0 ? available : PET_AVATAR_COLORS)[
      Math.floor(Math.random() * (available.length > 0 ? available.length : PET_AVATAR_COLORS.length))
    ];
    setPhotos((prev) => [...prev, nextColor]);
  }

  function removePhoto(index) {
    setPhotos((prev) => prev.filter((_, i) => i !== index));
  }

  const canSave =
    photos.length > 0 &&
    name.trim().length > 0 &&
    breed.trim().length > 0 &&
    microchipped !== null &&
    (microchipped === "no" || microchipNumber.trim().length > 0);

  function save() {
    onSave({
      id: `pet-${Date.now()}`,
      name: name.trim(),
      species,
      breed: breed.trim(),
      sex,
      birthday: birthday || null,
      primaryColor: primaryColor.trim(),
      markings: markings.trim(),
      microchipped: microchipped === "yes",
      microchipNumber: microchipped === "yes" ? microchipNumber.trim() : null,
      photos,
      // Avatar shown in lists is the first photo -- makes the pet card
      // reflect what was actually captured instead of an arbitrary color.
      color: photos[0],
    });
  }

  return (
    <div>
      <ScreenHeader title="Add Your Pet" onBack={onBack} />

      <div className="font-semibold text-sm mb-1.5">
        Photos ({photos.length}/{MAX_PET_PHOTOS})
      </div>
      <p className="text-xs mb-2" style={{ color: "#6B6459" }}>
        Add a few angles — it helps neighbors recognize {name.trim() || "your pet"} if they're ever missing.
      </p>
      <div className="flex gap-2 mb-6">
        {photos.map((color, i) => (
          <div
            key={i}
            className="amr-fade-in relative w-14 h-14 rounded-lg flex items-center justify-center shrink-0"
            style={{ background: color }}
          >
            <HeartMark size={22} color="#F2E9D8" />
            <button
              onClick={() => removePhoto(i)}
              aria-label="Remove photo"
              className="absolute -top-3 -right-3 w-11 h-11 rounded-full flex items-center justify-center"
            >
              {/* Visible badge stays small (matches the design); the button
                  itself is the full 44px minimum tap target (iOS HIG / Android
                  Material both require this) -- an invisible larger hit area
                  around a small visual dot, same technique iOS's own delete
                  badges use. */}
              <span
                className="w-5 h-5 rounded-full flex items-center justify-center text-xs font-bold"
                style={{ background: "#20291F", color: "#F2E9D8" }}
              >
                ×
              </span>
            </button>
          </div>
        ))}
        {photos.length < MAX_PET_PHOTOS && (
          <button
            onClick={addPhoto}
            className="amr-map w-14 h-14 rounded-lg flex items-center justify-center shrink-0"
            style={{ color: "#6B6459" }}
          >
            <Camera size={18} />
          </button>
        )}
      </div>

      <div className="font-semibold text-sm mb-1.5">Name</div>
      <input
        type="text"
        value={name}
        onChange={(e) => setName(e.target.value)}
        placeholder="Lucky"
        className="amr-chip w-full px-3 py-2.5 rounded-md text-sm mb-4"
      />

      <div className="font-semibold text-sm mb-1.5">Species</div>
      <select
        value={species}
        onChange={(e) => setSpecies(e.target.value)}
        className="amr-chip w-full px-3 py-2.5 rounded-md text-sm mb-4"
      >
        <option value="Dog">Dog</option>
        <option value="Cat">Cat</option>
        <option value="Other">Other</option>
      </select>

      <div className="font-semibold text-sm mb-1.5">Breed</div>
      <input
        type="text"
        value={breed}
        onChange={(e) => setBreed(e.target.value)}
        placeholder="Maltese"
        className="amr-chip w-full px-3 py-2.5 rounded-md text-sm mb-4"
      />

      <div className="font-semibold text-sm mb-1.5">Sex</div>
      <select
        value={sex}
        onChange={(e) => setSex(e.target.value)}
        className="amr-chip w-full px-3 py-2.5 rounded-md text-sm mb-4"
      >
        <option value="Female">Female</option>
        <option value="Male">Male</option>
      </select>

      <div className="font-semibold text-sm mb-1.5">Birthday</div>
      <input
        type="date"
        value={birthday}
        onChange={(e) => setBirthday(e.target.value)}
        max={new Date().toISOString().split("T")[0]}
        className="amr-chip w-full px-3 py-2.5 rounded-md text-sm mb-1"
      />
      <p className="text-xs mb-4" style={{ color: "#6B6459" }}>
        {birthday ? `Age: ${calculateAge(birthday)}` : "We'll calculate their age from this — an exact date isn't required, an estimate is fine."}
      </p>

      <div className="font-semibold text-sm mb-1.5">Primary color</div>
      <input
        type="text"
        value={primaryColor}
        onChange={(e) => setPrimaryColor(e.target.value)}
        placeholder="White"
        className="amr-chip w-full px-3 py-2.5 rounded-md text-sm mb-4"
      />

      <div className="font-semibold text-sm mb-1.5">Distinctive markings</div>
      <input
        type="text"
        value={markings}
        onChange={(e) => setMarkings(e.target.value)}
        placeholder="Brown spot near ear"
        className="amr-chip w-full px-3 py-2.5 rounded-md text-sm mb-4"
      />

      <div className="font-semibold text-sm mb-1.5">Microchipped?</div>
      <div className="flex gap-2 mb-4">
        <button
          onClick={() => setMicrochipped("yes")}
          className={`amr-chip flex-1 py-2 rounded-md text-sm ${microchipped === "yes" ? "amr-chip-active" : ""}`}
        >
          Yes
        </button>
        <button
          onClick={() => {
            setMicrochipped("no");
            setMicrochipNumber("");
          }}
          className={`amr-chip flex-1 py-2 rounded-md text-sm ${microchipped === "no" ? "amr-chip-active" : ""}`}
        >
          No
        </button>
      </div>

      {microchipped === "yes" && (
        <div className="amr-fade-in mb-4">
          <div className="font-semibold text-sm mb-1.5">Microchip number</div>
          <input
            type="password"
            value={microchipNumber}
            onChange={(e) => setMicrochipNumber(e.target.value)}
            placeholder="•••••••••••"
            className="amr-chip w-full px-3 py-2.5 rounded-md text-sm"
          />
        </div>
      )}

      <button disabled={!canSave} onClick={save} className="amr-btn-primary w-full py-3 rounded-md mt-2">
        Save Pet
      </button>
    </div>
  );
}

function AlertsScreen({ myActivePets, communityAlerts, foundPetsBoard, sightingsByPet, onOpenTrail, onReportSighting, onOpenProfile, onFoundPet, onMessageFinder }) {
  const hasAny = myActivePets.length > 0 || communityAlerts.length > 0;
  const [enlargedFoundPet, setEnlargedFoundPet] = useState(null);
  return (
    <div>
      <ScreenHeader title="Missing Pet Alerts" />
      <p className="text-sm mb-5" style={{ color: "#6B6459" }}>
        Every active search nearby, yours and the community's.
      </p>

      {!hasAny && (
        <p className="text-sm italic" style={{ color: "#6B6459" }}>
          No active alerts right now.
        </p>
      )}

      {myActivePets.length > 0 && (
        <div className="mb-6">
          <div className="font-semibold text-sm mb-2 flex items-center gap-2">
            <Bell size={15} />
            Your active searches
          </div>
          <div className="flex flex-col gap-3">
            {myActivePets.map((pet) => {
              const sightingCount = (sightingsByPet[pet.id] || []).length;
              return (
                <div
                  key={pet.id}
                  onClick={() => onOpenProfile(pet.id)}
                  className="amr-panel rounded-lg p-3.5"
                  style={{ cursor: "pointer" }}
                >
                  <div className="flex items-center gap-3 mb-3">
                    <div
                      className="w-10 h-10 rounded-full flex items-center justify-center text-white font-semibold shrink-0"
                      style={{ background: pet.color }}
                    >
                      {pet.name[0]}
                    </div>
                    <div className="flex-1 min-w-0">
                      <div className="font-semibold text-sm">{pet.name}</div>
                      <div className="text-xs" style={{ color: "#6B6459" }}>{pet.breed} · {pet.species}</div>
                    </div>
                    <div className="flex items-center gap-1.5 text-xs font-semibold" style={{ color: "#2F6E62" }}>
                      <span className="w-2 h-2 rounded-full amr-pulse" style={{ background: "#2F6E62" }} />
                      ACTIVE
                    </div>
                  </div>
                  <div className="text-xs mb-3" style={{ color: "#6B6459" }}>
                    👀 {sightingCount} sighting{sightingCount === 1 ? "" : "s"} reported
                  </div>
                  <button
                    onClick={(e) => { e.stopPropagation(); onOpenTrail(pet.id); }}
                    className="amr-btn-teal w-full py-2 rounded-md text-sm"
                  >
                    View sighting trail
                  </button>
                </div>
              );
            })}
          </div>
        </div>
      )}

      {communityAlerts.length > 0 && (
        <div>
          <div className="font-semibold text-sm mb-2 flex items-center gap-2">
            <Users size={15} />
            Nearby missing pets
          </div>
          <div className="flex flex-col gap-3">
            {communityAlerts.map((pet) => {
              const sightingCount = (sightingsByPet[pet.id] || []).length;
              return (
                <div
                  key={pet.id}
                  onClick={() => onOpenProfile(pet.id)}
                  className="amr-panel rounded-lg p-3.5"
                  style={{ cursor: "pointer" }}
                >
                  <div className="flex items-center gap-3 mb-2">
                    <div
                      className="w-10 h-10 rounded-full flex items-center justify-center text-white font-semibold shrink-0"
                      style={{ background: pet.color }}
                    >
                      {pet.name[0]}
                    </div>
                    <div className="flex-1 min-w-0">
                      <div className="font-semibold text-sm">{pet.name}</div>
                      <div className="text-xs" style={{ color: "#6B6459" }}>{pet.breed} · {pet.species} · owner: {pet.ownerName}</div>
                    </div>
                  </div>
                  <div className="flex items-center justify-between text-xs mb-1" style={{ color: "#6B6459" }}>
                    <span>Last seen {pet.lastSeenLabel} · {pet.distanceLabel}</span>
                    <span>{pet.radiusKm} km radius</span>
                  </div>
                  <div className="text-xs mb-3" style={{ color: "#6B6459" }}>
                    👀 {sightingCount} sighting{sightingCount === 1 ? "" : "s"} reported
                  </div>
                  <button
                    onClick={(e) => { e.stopPropagation(); onReportSighting(pet.id); }}
                    className="amr-btn-secondary w-full py-2 rounded-md text-sm flex items-center justify-center gap-2"
                  >
                    <Camera size={15} />
                    Report a sighting of {pet.name}
                  </button>
                </div>
              );
            })}
          </div>
        </div>
      )}

      <div className="amr-panel rounded-lg p-4 mt-6">
        <div className="flex items-center gap-2 mb-1.5">
          <HeartMark size={16} />
          <span className="font-semibold text-sm">Found a pet you don't recognize?</span>
        </div>
        <p className="text-xs mb-3" style={{ color: "#6B6459" }}>
          We'll check it against active missing-pet reports nearby.
        </p>
        <button onClick={onFoundPet} className="amr-btn-secondary w-full py-2 rounded-md text-sm flex items-center justify-center gap-2">
          <Camera size={15} />
          Report a Found Pet
        </button>
      </div>

      {foundPetsBoard.length > 0 && (
        <div className="mt-6">
          <div className="font-semibold text-sm mb-2">Found Pets Board</div>
          <p className="text-xs mb-3" style={{ color: "#6B6459" }}>
            Found pets that didn't match an active report. If one might be yours, contact local shelters or check back.
          </p>
          <div className="flex flex-col gap-3">
            {foundPetsBoard.map((f) => (
              <div key={f.id} className="amr-panel rounded-lg p-3.5">
                <div className="flex items-center gap-3 mb-2">
                  <button
                    onClick={() => (f.photos?.length > 0 || f.photoColor) && setEnlargedFoundPet(f)}
                    className="w-11 h-11 rounded-lg flex items-center justify-center shrink-0"
                    style={{ background: f.photoColor, cursor: f.photos?.length > 0 || f.photoColor ? "pointer" : "default" }}
                    aria-label="View photo"
                  >
                    <HeartMark size={20} color="#F2E9D8" />
                  </button>
                  <div className="flex-1 min-w-0">
                    <div className="text-sm font-semibold">{f.species} · {f.primaryColor}</div>
                    <div className="text-xs" style={{ color: "#6B6459" }}>
                      {f.locationLabel} · {f.timeLabel} · found by {f.finderName}
                    </div>
                  </div>
                </div>
                {f.comment && (
                  <div className="text-xs p-2.5 rounded-md mb-3" style={{ background: "#EDE3CD" }}>
                    <span className="font-semibold" style={{ color: "#20291F" }}>💬 {f.finderName}: </span>
                    <span style={{ color: "#6B6459" }}>"{f.comment}"</span>
                  </div>
                )}
                <button
                  onClick={() => onMessageFinder(f)}
                  className="amr-btn-secondary w-full py-1.5 rounded-md text-xs flex items-center justify-center gap-1.5"
                >
                  <MessageCircle size={13} />
                  Message {f.finderName}
                </button>
              </div>
            ))}
          </div>
        </div>
      )}

      {enlargedFoundPet && (
        <PhotoLightbox
          photos={enlargedFoundPet.photos?.length > 0 ? enlargedFoundPet.photos : [enlargedFoundPet.photoColor]}
          title={`${enlargedFoundPet.species} · ${enlargedFoundPet.primaryColor}`}
          subtitle={`${enlargedFoundPet.locationLabel} · ${enlargedFoundPet.timeLabel}`}
          onClose={() => setEnlargedFoundPet(null)}
        />
      )}
    </div>
  );
}

function StatRow({ emoji, label, value, isLast }) {
  return (
    <div
      className="flex items-center justify-between py-2"
      style={!isLast ? { borderBottom: "1px solid #CBBFA0" } : undefined}
    >
      <span className="text-sm font-medium">{emoji} {label}</span>
      <span className="font-semibold text-sm">{value}</span>
    </div>
  );
}

