function ChangePasswordScreen({ onBack }) {
  const [current, setCurrent] = useState("");
  const [next, setNext] = useState("");
  const [confirm, setConfirm] = useState("");
  const [saved, setSaved] = useState(false);

  const canSave = current.length > 0 && next.length >= 8 && next === confirm;

  function save() {
    setSaved(true);
    setCurrent("");
    setNext("");
    setConfirm("");
  }

  return (
    <div>
      <ScreenHeader title="Change Password" onBack={onBack} />

      {saved && (
        <div className="amr-fade-in mb-4 rounded-md p-3 text-sm" style={{ background: "#DED9C0", border: "2px solid #2F6E62", color: "#20291F" }}>
          Password updated.
        </div>
      )}

      <div className="font-semibold text-sm mb-1.5">Current password</div>
      <input
        type="password"
        value={current}
        onChange={(e) => { setCurrent(e.target.value); setSaved(false); }}
        className="amr-chip w-full px-3 py-2.5 rounded-md text-sm mb-4"
      />

      <div className="font-semibold text-sm mb-1.5">New password</div>
      <input
        type="password"
        value={next}
        onChange={(e) => { setNext(e.target.value); setSaved(false); }}
        placeholder="At least 8 characters"
        className="amr-chip w-full px-3 py-2.5 rounded-md text-sm mb-4"
      />

      <div className="font-semibold text-sm mb-1.5">Confirm new password</div>
      <input
        type="password"
        value={confirm}
        onChange={(e) => { setConfirm(e.target.value); setSaved(false); }}
        className="amr-chip w-full px-3 py-2.5 rounded-md text-sm mb-5"
      />

      <button disabled={!canSave} onClick={save} className="amr-btn-primary w-full py-3 rounded-md">
        Save New Password
      </button>
    </div>
  );
}

function NotificationSettingsScreen({ onBack }) {
  const [prefs, setPrefs] = useState({
    sightingAlerts: true,
    ownerAlerts: true,
    messages: true,
    communityActivity: false,
  });

  const rows = [
    { key: "sightingAlerts", label: "Sighting Alerts", hint: "New sightings on your active cases" },
    { key: "ownerAlerts", label: "Owner Alerts", hint: "Credible-confidence notifications" },
    { key: "messages", label: "Messages", hint: "Replies from reporters, finders, or Amari" },
    { key: "communityActivity", label: "Community Activity", hint: "Likes and comments on your posts" },
  ];

  return (
    <div>
      <ScreenHeader title="Notifications" onBack={onBack} />
      <div className="amr-panel rounded-lg overflow-hidden">
        {rows.map((row, i) => (
          <div
            key={row.key}
            className="flex items-center justify-between px-4 py-3.5"
            style={i < rows.length - 1 ? { borderBottom: "1px solid #CBBFA0" } : undefined}
          >
            <div className="pr-3">
              <div className="text-sm font-medium">{row.label}</div>
              <div className="text-xs mt-0.5" style={{ color: "#6B6459" }}>{row.hint}</div>
            </div>
            <button
              onClick={() => setPrefs((p) => ({ ...p, [row.key]: !p[row.key] }))}
              className="shrink-0 w-11 h-6 rounded-full relative"
              style={{ background: prefs[row.key] ? "#2F6E62" : "#CBBFA0" }}
              aria-label={`Toggle ${row.label}`}
            >
              <span
                className="absolute top-0.5 w-5 h-5 rounded-full bg-white transition-all"
                style={{ left: prefs[row.key] ? "22px" : "2px" }}
              />
            </button>
          </div>
        ))}
      </div>
    </div>
  );
}

