function ProfileEditScreen({ userProfile, onSave, onBack }) {
  const [fullName, setFullName] = useState(userProfile.fullName);
  const [phone, setPhone] = useState(userProfile.phone);
  const [email, setEmail] = useState(userProfile.email);
  const [address, setAddress] = useState(userProfile.address);
  const [emergencyContactName, setEmergencyContactName] = useState(userProfile.emergencyContactName);
  const [emergencyContactPhone, setEmergencyContactPhone] = useState(userProfile.emergencyContactPhone);

  const canSave = fullName.trim().length > 0 && (phone.trim().length > 0 || email.trim().length > 0);

  function save() {
    onSave({
      fullName: fullName.trim(),
      phone: phone.trim(),
      email: email.trim(),
      address: address.trim(),
      emergencyContactName: emergencyContactName.trim(),
      emergencyContactPhone: emergencyContactPhone.trim(),
    });
  }

  return (
    <div>
      <ScreenHeader title="Edit Profile" onBack={onBack} />

      <div className="font-semibold text-sm mb-1.5">Full name</div>
      <input
        type="text"
        value={fullName}
        onChange={(e) => setFullName(e.target.value)}
        placeholder="Your name"
        className="amr-chip w-full px-3 py-2.5 rounded-md text-sm mb-4"
      />

      <div className="font-semibold text-sm mb-1.5">Phone</div>
      <input
        type="tel"
        value={phone}
        onChange={(e) => setPhone(e.target.value)}
        placeholder="(555) 555-0100"
        className="amr-chip w-full px-3 py-2.5 rounded-md text-sm mb-4"
      />

      <div className="font-semibold text-sm mb-1.5">Email</div>
      <input
        type="email"
        value={email}
        onChange={(e) => setEmail(e.target.value)}
        placeholder="you@example.com"
        className="amr-chip w-full px-3 py-2.5 rounded-md text-sm mb-4"
      />

      <div className="font-semibold text-sm mb-1.5">Home address</div>
      <input
        type="text"
        value={address}
        onChange={(e) => setAddress(e.target.value)}
        placeholder="Street, neighborhood, or city"
        className="amr-chip w-full px-3 py-2.5 rounded-md text-sm mb-1"
      />
      <p className="text-xs mb-4" style={{ color: "#6B6459" }}>
        Used to suggest a starting location if a pet goes missing from home. Never shown publicly.
      </p>

      <div className="font-semibold text-sm mb-1.5">Emergency contact name</div>
      <input
        type="text"
        value={emergencyContactName}
        onChange={(e) => setEmergencyContactName(e.target.value)}
        placeholder="Someone who can help if you're unreachable"
        className="amr-chip w-full px-3 py-2.5 rounded-md text-sm mb-4"
      />

      <div className="font-semibold text-sm mb-1.5">Emergency contact phone</div>
      <input
        type="tel"
        value={emergencyContactPhone}
        onChange={(e) => setEmergencyContactPhone(e.target.value)}
        placeholder="(555) 555-0100"
        className="amr-chip w-full px-3 py-2.5 rounded-md text-sm mb-5"
      />

      <button disabled={!canSave} onClick={save} className="amr-btn-primary w-full py-3 rounded-md">
        Save Profile
      </button>
    </div>
  );
}

function ReunionStoryScreen({ story, onBack }) {
  if (!story) return null;
  // Public feed stories carry heroName/ownerName/photoColor/timeLabel; the
  // private thank-you-message shape (from Profile) doesn't, and gets the
  // simpler original treatment.
  const isPublicStory = !!story.heroName;
  return (
    <div>
      <ScreenHeader title="Reunion Story" onBack={onBack} />
      <div className="text-center pt-4">
        {isPublicStory ? (
          <div
            className="w-full h-40 rounded-lg mb-4 flex items-center justify-center"
            style={{ background: story.photoColor }}
          >
            <Heart size={40} color="#F2E9D8" fill="#F2E9D8" />
          </div>
        ) : (
          <div className="flex justify-center mb-4">
            <Heart size={48} color="#E2572B" fill="#E2572B" />
          </div>
        )}
        <div className="amr-panel rounded-lg p-4 text-left">
          {isPublicStory && (
            <div className="font-semibold text-sm mb-2">{story.petName} is home ❤️</div>
          )}
          {isPublicStory && story.lostDateLabel && story.foundDateLabel && (
            <div className="flex items-center gap-2 text-xs mb-3 pb-3" style={{ color: "#6B6459", borderBottom: "1px solid #CBBFA0" }}>
              <span>🗓️ Missing since {story.lostDateLabel}</span>
              <span>·</span>
              <span>❤️ Found {story.foundDateLabel}</span>
            </div>
          )}
          <p className="text-sm italic mb-3">"{story.message}"</p>
          {isPublicStory ? (
            <>
              <p className="text-xs" style={{ color: "#6B6459" }}>
                — {story.ownerName}, {story.petName}'s owner
              </p>
              <p className="text-xs mt-1" style={{ color: "#6B6459" }}>
                🏅 Hero: {story.heroName} · {story.timeLabel}
              </p>
            </>
          ) : (
            <p className="text-xs" style={{ color: "#6B6459" }}>— Owner of {story.petName}</p>
          )}
        </div>
      </div>
    </div>
  );
}

function PetProfileScreen({ pet, isOwnPet, isActive, sightingCount, onBack, onViewTrail, onReportSighting, onReportMissing }) {
  const photos = pet.photos && pet.photos.length > 0 ? pet.photos : [pet.color];
  const [lightboxIndex, setLightboxIndex] = useState(null); // index into photos, or null when closed
  return (
    <div>
      <ScreenHeader title={`${pet.name}'s Profile`} onBack={onBack} />

      <div className="flex gap-2 mb-5 overflow-x-auto">
        {photos.map((color, i) => (
          <button
            key={i}
            onClick={() => setLightboxIndex(i)}
            className="w-20 h-20 rounded-lg flex items-center justify-center shrink-0"
            style={{ background: color }}
            aria-label="View photo"
          >
            <HeartMark size={30} color="#F2E9D8" />
          </button>
        ))}
      </div>

      {lightboxIndex !== null && (
        <PhotoLightbox
          photos={photos}
          startIndex={lightboxIndex}
          title={pet.name}
          subtitle={`${pet.breed} · ${pet.species}`}
          onClose={() => setLightboxIndex(null)}
        />
      )}

      <div className="amr-panel rounded-lg p-4 mb-5">
        <div className="flex items-center gap-3 mb-3">
          <div
            className="w-12 h-12 rounded-full flex items-center justify-center text-white font-semibold text-lg shrink-0"
            style={{ background: pet.color }}
          >
            {pet.name[0]}
          </div>
          <div>
            <div className="font-semibold text-lg">{pet.name}</div>
            <div className="text-xs" style={{ color: "#6B6459" }}>{pet.breed} · {pet.species}</div>
          </div>
        </div>

        <div className="text-sm space-y-2">
          {pet.sex && (
            <div className="flex justify-between gap-3">
              <span style={{ color: "#6B6459" }}>Sex</span>
              <span className="font-medium text-right">{pet.sex}</span>
            </div>
          )}
          {pet.birthday && (
            <div className="flex justify-between gap-3">
              <span style={{ color: "#6B6459" }}>Age</span>
              <span className="font-medium text-right">{calculateAge(pet.birthday)}</span>
            </div>
          )}
          {pet.primaryColor && (
            <div className="flex justify-between gap-3">
              <span style={{ color: "#6B6459" }}>Primary color</span>
              <span className="font-medium text-right">{pet.primaryColor}</span>
            </div>
          )}
          {pet.markings && (
            <div className="flex justify-between gap-3">
              <span style={{ color: "#6B6459" }}>Distinctive markings</span>
              <span className="font-medium text-right">{pet.markings}</span>
            </div>
          )}
          {pet.microchipped !== undefined && (
            <div className="flex justify-between gap-3">
              <span style={{ color: "#6B6459" }}>Microchipped</span>
              <span className="font-medium text-right">
                {pet.microchipped ? `Yes${pet.microchipNumber ? ` (${pet.microchipNumber})` : ""}` : "No"}
              </span>
            </div>
          )}
          {!isOwnPet && (
            <>
              <div className="flex justify-between gap-3">
                <span style={{ color: "#6B6459" }}>Owner</span>
                <span className="font-medium text-right">{pet.ownerName}</span>
              </div>
              <div className="flex justify-between gap-3">
                <span style={{ color: "#6B6459" }}>Last seen</span>
                <span className="font-medium text-right">{pet.lastSeenLabel} · {pet.distanceLabel}</span>
              </div>
            </>
          )}
        </div>
      </div>

      <div className="text-sm mb-4" style={{ color: "#6B6459" }}>
        👀 {sightingCount} sighting{sightingCount === 1 ? "" : "s"} reported
      </div>

      {isOwnPet && isActive && (
        <button onClick={onViewTrail} className="amr-btn-teal w-full py-3 rounded-md">
          View Sighting Trail
        </button>
      )}
      {isOwnPet && !isActive && (
        <button onClick={onReportMissing} className="amr-btn-primary w-full py-3 rounded-md">
          Report Missing
        </button>
      )}
      {!isOwnPet && (
        <button onClick={onReportSighting} className="amr-btn-secondary w-full py-3 rounded-md flex items-center justify-center gap-2">
          <Camera size={15} />
          Report a Sighting
        </button>
      )}
    </div>
  );
}

