function Onboarding({ onComplete }) {
  // welcome | contact | code | profileDetails | idType | idCapture | verifying | verified
  const [stage, setStage] = useState("welcome");
  const [contact, setContact] = useState("");
  const [contactMethod, setContactMethod] = useState("email");
  const [code, setCode] = useState("");
  const [fullName, setFullName] = useState("");
  const [address, setAddress] = useState("");
  const [emergencyContactName, setEmergencyContactName] = useState("");
  const [emergencyContactPhone, setEmergencyContactPhone] = useState("");
  const [idType, setIdType] = useState(null);
  const [idCaptured, setIdCaptured] = useState(false);

  return (
    <div>
      {stage === "welcome" && <WelcomeStep onContinue={() => setStage("contact")} />}
      {stage === "contact" && (
        <ContactStep
          contact={contact}
          setContact={setContact}
          contactMethod={contactMethod}
          setContactMethod={setContactMethod}
          onBack={() => setStage("welcome")}
          onContinue={() => setStage("code")}
        />
      )}
      {stage === "code" && (
        <CodeStep
          contact={contact}
          contactMethod={contactMethod}
          code={code}
          setCode={setCode}
          onBack={() => setStage("contact")}
          onContinue={() => setStage("profileDetails")}
        />
      )}
      {stage === "profileDetails" && (
        <ProfileDetailsStep
          fullName={fullName}
          setFullName={setFullName}
          address={address}
          setAddress={setAddress}
          emergencyContactName={emergencyContactName}
          setEmergencyContactName={setEmergencyContactName}
          emergencyContactPhone={emergencyContactPhone}
          setEmergencyContactPhone={setEmergencyContactPhone}
          onBack={() => setStage("code")}
          onContinue={() => setStage("idType")}
        />
      )}
      {stage === "idType" && (
        <IdTypeStep idType={idType} setIdType={setIdType} onBack={() => setStage("profileDetails")} onContinue={() => setStage("idCapture")} />
      )}
      {stage === "idCapture" && (
        <IdCaptureStep
          idType={idType}
          idCaptured={idCaptured}
          setIdCaptured={setIdCaptured}
          onBack={() => setStage("idType")}
          onContinue={() => setStage("verifying")}
        />
      )}
      {stage === "verifying" && <VerifyingStep onDone={() => setStage("verified")} />}
      {stage === "verified" && (
        <VerifiedStep
          onContinue={() =>
            onComplete({ contact, contactMethod, fullName, address, emergencyContactName, emergencyContactPhone })
          }
        />
      )}
    </div>
  );
}

function OnboardingHeader({ step, total, onBack }) {
  return (
    <div className="flex items-center justify-between mb-6">
      <div className="flex items-center gap-1.5">
        {onBack ? (
          <button onClick={onBack} className="p-2.5 -ml-2.5 rounded-full hover:bg-black/5" aria-label="Back">
            <ChevronLeft size={30} />
          </button>
        ) : (
          <HeartMark size={30} />
        )}
        <Wordmark size="text-xl" />
      </div>
      {step && <span className="text-xs" style={{ color: "#6B6459" }}>Step {step} of {total}</span>}
    </div>
  );
}

function ContactStep({ contact, setContact, contactMethod, setContactMethod, onBack, onContinue }) {
  const isValid = contactMethod === "email" ? /\S+@\S+\.\S+/.test(contact) : contact.replace(/\D/g, "").length >= 7;
  return (
    <div>
      <OnboardingHeader step={1} total={5} onBack={onBack} />
      <div className="amr-display text-4xl leading-none mb-1">JOIN THE SEARCH</div>
      <p className="text-sm mb-5" style={{ color: "#6B6459" }}>
        REunited only alerts verified people, so every account starts with
        a quick verification.
      </p>

      <div className="flex gap-2 mb-3">
        <button onClick={() => { setContactMethod("email"); setContact(""); }} className={`amr-chip flex-1 py-2 rounded-md text-sm ${contactMethod === "email" ? "amr-chip-active" : ""}`}>
          Email
        </button>
        <button onClick={() => { setContactMethod("phone"); setContact(""); }} className={`amr-chip flex-1 py-2 rounded-md text-sm ${contactMethod === "phone" ? "amr-chip-active" : ""}`}>
          Phone
        </button>
      </div>

      <input
        type={contactMethod === "email" ? "email" : "tel"}
        value={contact}
        onChange={(e) => setContact(e.target.value)}
        placeholder={contactMethod === "email" ? "you@example.com" : "(555) 555-0100"}
        className="amr-chip w-full px-3 py-2.5 rounded-md text-sm mb-5"
      />

      <button disabled={!isValid} onClick={onContinue} className="amr-btn-primary w-full py-3 rounded-md">
        Send verification code
      </button>
    </div>
  );
}

function CodeStep({ contact, contactMethod, code, setCode, onBack, onContinue }) {
  return (
    <div>
      <OnboardingHeader step={2} total={5} onBack={onBack} />
      <div className="amr-display text-4xl leading-none mb-1">CHECK YOUR {contactMethod === "email" ? "INBOX" : "PHONE"}</div>
      <p className="text-sm mb-5" style={{ color: "#6B6459" }}>
        We sent a 6-digit code to <span className="font-medium">{contact || "your contact"}</span>.
      </p>

      <input
        type="text"
        inputMode="numeric"
        maxLength={6}
        value={code}
        onChange={(e) => setCode(e.target.value.replace(/\D/g, ""))}
        placeholder="123456"
        className="amr-chip w-full px-3 py-2.5 rounded-md text-sm mb-2 text-center tracking-[0.3em] font-semibold"
      />
      <p className="text-xs mb-5" style={{ color: "#6B6459" }}>Demo mode — any 6 digits will work.</p>

      <button disabled={code.length !== 6} onClick={onContinue} className="amr-btn-primary w-full py-3 rounded-md">
        Verify code
      </button>
    </div>
  );
}

function ProfileDetailsStep({
  fullName, setFullName, address, setAddress,
  emergencyContactName, setEmergencyContactName, emergencyContactPhone, setEmergencyContactPhone,
  onBack, onContinue,
}) {
  const canContinue = fullName.trim().length > 0;
  return (
    <div>
      <OnboardingHeader step={3} total={5} onBack={onBack} />
      <div className="amr-display text-4xl leading-none mb-1">TELL US ABOUT YOU</div>
      <p className="text-sm mb-5" style={{ color: "#6B6459" }}>
        This is what helps people reach you fastest if your pet ever goes missing.
      </p>

      <div className="font-semibold text-sm mb-1.5">Full name</div>
      <input
        type="text"
        value={fullName}
        onChange={(e) => setFullName(e.target.value)}
        placeholder="Your name"
        className="amr-chip w-full px-3 py-2.5 rounded-md text-sm mb-4"
      />

      <div className="font-semibold text-sm mb-1.5">Home address (optional)</div>
      <input
        type="text"
        value={address}
        onChange={(e) => setAddress(e.target.value)}
        placeholder="Street, neighborhood, or city"
        className="amr-chip w-full px-3 py-2.5 rounded-md text-sm mb-1"
      />
      <p className="text-xs mb-4" style={{ color: "#6B6459" }}>
        Helps default a case's starting location. Never shown publicly.
      </p>

      <div className="font-semibold text-sm mb-1.5">Emergency contact name (optional)</div>
      <input
        type="text"
        value={emergencyContactName}
        onChange={(e) => setEmergencyContactName(e.target.value)}
        placeholder="Someone who can help if you're unreachable"
        className="amr-chip w-full px-3 py-2.5 rounded-md text-sm mb-4"
      />

      <div className="font-semibold text-sm mb-1.5">Emergency contact phone (optional)</div>
      <input
        type="tel"
        value={emergencyContactPhone}
        onChange={(e) => setEmergencyContactPhone(e.target.value)}
        placeholder="(555) 555-0100"
        className="amr-chip w-full px-3 py-2.5 rounded-md text-sm mb-5"
      />

      <button disabled={!canContinue} onClick={onContinue} className="amr-btn-primary w-full py-3 rounded-md">
        Continue
      </button>
      <p className="text-xs text-center mt-2" style={{ color: "#6B6459" }}>
        You can always add or update this later from your Profile.
      </p>
    </div>
  );
}

function IdTypeStep({ idType, setIdType, onBack, onContinue }) {
  return (
    <div>
      <OnboardingHeader step={4} total={5} onBack={onBack} />
      <div className="amr-display text-4xl leading-none mb-1">CONFIRM YOU'RE REAL</div>
      <p className="text-sm mb-5" style={{ color: "#6B6459" }}>
        One more step keeps REunited trustworthy for pet owners and
        finders alike. Pick an ID to verify with.
      </p>

      <div className="flex flex-col gap-2 mb-6">
        {[
          { key: "government", label: "Government-issued ID", hint: "Driver's license, passport, or national ID" },
          { key: "school", label: "School ID", hint: "Student or staff ID card" },
        ].map((opt) => (
          <button
            key={opt.key}
            onClick={() => setIdType(opt.key)}
            className={`amr-chip w-full text-left px-3.5 py-3 rounded-md ${idType === opt.key ? "amr-chip-active" : ""}`}
          >
            <div className="text-sm font-semibold">{opt.label}</div>
            <div className="text-xs" style={{ color: idType === opt.key ? "#CBBFA0" : "#6B6459" }}>{opt.hint}</div>
          </button>
        ))}
      </div>

      <button disabled={!idType} onClick={onContinue} className="amr-btn-primary w-full py-3 rounded-md">
        Continue
      </button>
    </div>
  );
}

function IdCaptureStep({ idType, idCaptured, setIdCaptured, onBack, onContinue }) {
  return (
    <div>
      <OnboardingHeader step={5} total={5} onBack={onBack} />
      <div className="amr-display text-4xl leading-none mb-1">PHOTOGRAPH YOUR ID</div>
      <p className="text-sm mb-5" style={{ color: "#6B6459" }}>
        Make sure all four corners are visible and the text is easy to read.
      </p>

      <div
        onClick={!idCaptured ? () => setIdCaptured(true) : undefined}
        className="amr-map relative w-full h-40 rounded-lg overflow-hidden mb-2 flex items-center justify-center"
        style={{ cursor: idCaptured ? "default" : "pointer" }}
      >
        {!idCaptured ? (
          <div className="flex flex-col items-center gap-2" style={{ color: "#6B6459" }}>
            <Camera size={26} />
            <span className="text-sm font-semibold">Tap to photograph your {idType === "school" ? "school ID" : "ID"}</span>
          </div>
        ) : (
          <div className="amr-fade-in flex flex-col items-center gap-2" style={{ color: "#2F6E62" }}>
            <CheckCircle2 size={36} />
            <span className="text-xs font-semibold" style={{ color: "#6B6459" }}>ID captured</span>
          </div>
        )}
      </div>
      <p className="text-xs mb-5" style={{ color: "#6B6459" }}>
        Your ID photo is used only to verify your identity and isn't shown to
        other users.
      </p>

      <button disabled={!idCaptured} onClick={onContinue} className="amr-btn-primary w-full py-3 rounded-md">
        Submit for verification
      </button>
    </div>
  );
}

function VerifyingStep({ onDone }) {
  const [stageIndex, setStageIndex] = useState(0);
  const done = stageIndex >= VERIFICATION_STAGES.length;

  useEffect(() => {
    if (done) {
      const t = setTimeout(onDone, 500);
      return () => clearTimeout(t);
    }
    const t = setTimeout(() => setStageIndex((i) => i + 1), 700);
    return () => clearTimeout(t);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [stageIndex]);

  return (
    <div className="text-center pt-6">
      <div className="flex justify-center mb-4">
        <RotateCw size={36} className="animate-spin" color="#20291F" />
      </div>
      <div className="amr-display text-4xl mb-1">VERIFYING</div>
      <p className="text-sm mb-6" style={{ color: "#6B6459" }}>This usually takes just a moment.</p>
      <div className="amr-panel rounded-lg p-4 text-left">
        {VERIFICATION_STAGES.map((s, i) => (
          <div key={s.key} className="flex items-center gap-2.5 py-1.5">
            {i < stageIndex ? (
              <CheckCircle2 size={16} color="#2F6E62" />
            ) : i === stageIndex ? (
              <RotateCw size={16} className="animate-spin" color="#6B6459" />
            ) : (
              <span className="w-4 h-4 rounded-full" style={{ border: "2px solid #CBBFA0" }} />
            )}
            <span className="text-sm" style={{ color: i <= stageIndex ? "#20291F" : "#6B6459" }}>{s.label}</span>
          </div>
        ))}
      </div>
    </div>
  );
}

function VerifiedStep({ onContinue }) {
  return (
    <div className="text-center pt-6">
      <div className="flex justify-center mb-4">
        <div className="w-16 h-16 rounded-full flex items-center justify-center" style={{ background: "#2F6E62" }}>
          <CheckCircle2 size={32} color="#F2E9D8" />
        </div>
      </div>
      <div className="amr-display text-4xl mb-1" style={{ color: "#2F6E62" }}>YOU'RE VERIFIED</div>
      <p className="text-sm mb-6" style={{ color: "#6B6459" }}>
        You can now create pet profiles, report a missing pet, and help
        reunite others nearby.
      </p>
      <button onClick={onContinue} className="amr-btn-teal w-full py-3 rounded-md">
        Continue to REunited
      </button>
    </div>
  );
}

// ---------------------------------------------------------------------------
// Admin dashboard -- platform-staff view, entirely separate from the
// consumer app. Deliberately styled differently (dark header, color-coded
// triage borders) since this is a genuinely different kind of tool -- an
// ops dashboard, not a warm community app -- for a different audience.
//
// Mock data generators build realistic-looking sample lists so each stat
// tile can be drilled into. Identity/Photo reviews and User Reports are
// genuinely actionable here (Approve/Reject/Resolve actually remove the
// item and the tile's count updates live) since those are admin-driven
// actions. Active Cases and Reunited Today are read-only samples -- those
// are owner-driven outcomes, not something an admin resolves directly, and
// 142/14 are illustrative totals rather than the full underlying dataset.
// ---------------------------------------------------------------------------

const MOCK_FIRST_NAMES = ["Alex", "Priya", "Diego", "Casey", "Jordan", "Sam", "Marcus", "Ana", "Riley", "Noah", "Grace", "Liam", "Sofia", "Ethan", "Mia"];
const MOCK_LAST_INITIALS = ["R.", "N.", "M.", "L.", "T.", "K.", "P.", "S.", "D.", "W."];
function mockPersonName(i) {
  return `${MOCK_FIRST_NAMES[i % MOCK_FIRST_NAMES.length]} ${MOCK_LAST_INITIALS[(i * 3) % MOCK_LAST_INITIALS.length]}`;
}

function buildIdentityReviews(count) {
  const idTypes = ["Government ID", "School ID"];
  return Array.from({ length: count }, (_, i) => ({
    id: `idr-${i}`,
    applicantName: mockPersonName(i),
    idType: idTypes[i % idTypes.length],
    submittedLabel: `${(i % 6) + 1} hr ago`,
  }));
}

function buildPhotoReviews(count) {
  const reasons = ["Possible AI-generation flag", "Low image quality", "Metadata mismatch", "Duplicate image detected"];
  const petNames = ["Milo", "Rex", "Coco", "Luna", "Buddy", "Nala", "Rocky", "Bella"];
  return Array.from({ length: count }, (_, i) => ({
    id: `pr-${i}`,
    petName: petNames[i % petNames.length],
    submitterName: mockPersonName(i + 2),
    reason: reasons[i % reasons.length],
    timeLabel: `${(i % 12) + 1} min ago`,
  }));
}

function buildUserReports(count) {
  const reasons = ["Spam sightings", "Inappropriate photo", "Harassment", "Suspicious activity"];
  return Array.from({ length: count }, (_, i) => ({
    id: `ur-${i}`,
    reportedUser: mockPersonName(i + 5),
    reportedBy: mockPersonName(i + 1),
    reason: reasons[i % reasons.length],
    timeLabel: `${(i % 5) + 1} hr ago`,
  }));
}

function buildActiveCasesSample(count) {
  const petNames = ["Rex", "Coco", "Bailey", "Shadow", "Daisy", "Zeus", "Piper", "Oreo", "Simba", "Rosie"];
  const speciesList = ["Dog", "Cat"];
  const radii = [1, 3, 5];
  return Array.from({ length: count }, (_, i) => ({
    id: `case-${i}`,
    petName: petNames[i % petNames.length],
    species: speciesList[i % 2],
    ownerName: mockPersonName(i + 8),
    lastSeenLabel: `${(i % 8) + 1} hr ago`,
    radiusKm: radii[i % 3],
  }));
}

function buildReunitedToday(count) {
  const petNames = ["Max", "Milo", "Luna", "Bailey", "Rocky", "Nala", "Daisy", "Oreo", "Piper", "Simba", "Rosie", "Zeus", "Coco", "Bella"];
  return Array.from({ length: count }, (_, i) => ({
    id: `reunited-${i}`,
    petName: petNames[i % petNames.length],
    ownerName: mockPersonName(i + 3),
    timeLabel: `${(i % 10) + 1} hr ago`,
    heroName: i % 3 === 0 ? mockPersonName(i + 7) : null,
  }));
}

const ADMIN_CATEGORY_TITLES = {
  activeCases: "Active Missing Cases",
  idReviews: "Identity Reviews",
  photoReviews: "Photo Reviews",
  userReports: "User Reports",
  messages: "Messages",
  reunitedToday: "Reunited Today",
};

function AdminDashboardScreen({ onExit, feedbackMessages, onSendReply }) {
  const [drilldown, setDrilldown] = useState(null);
  const [identityReviews, setIdentityReviews] = useState(() => buildIdentityReviews(18));
  const [photoReviews, setPhotoReviews] = useState(() => buildPhotoReviews(27));
  const [userReports, setUserReports] = useState(() => buildUserReports(6));
  const [activeCasesSample] = useState(() => buildActiveCasesSample(10));
  const [reunitedTodayList] = useState(() => buildReunitedToday(14));

  const stats = [
    { key: "activeCases", emoji: "🚨", label: "Active Missing Cases", value: 142, accent: "#E2572B" },
    { key: "idReviews", emoji: "⏳", label: "Identity Reviews", value: identityReviews.length, accent: "#6B6459" },
    { key: "photoReviews", emoji: "📷", label: "Photo Reviews", value: photoReviews.length, accent: "#6B6459" },
    { key: "userReports", emoji: "🚩", label: "User Reports", value: userReports.length, accent: "#E2572B" },
    { key: "messages", emoji: "💬", label: "Messages", value: feedbackMessages.length, accent: "#2F6E62" },
    { key: "reunitedToday", emoji: "❤️", label: "Reunited Today", value: 14, accent: "#2F6E62" },
  ];

  if (drilldown) {
    return (
      <AdminDrilldownScreen
        category={drilldown}
        onBack={() => setDrilldown(null)}
        identityReviews={identityReviews}
        photoReviews={photoReviews}
        userReports={userReports}
        activeCasesSample={activeCasesSample}
        reunitedTodayList={reunitedTodayList}
        feedbackMessages={feedbackMessages}
        onSendReply={onSendReply}
        onApproveIdentity={(id) => setIdentityReviews((prev) => prev.filter((r) => r.id !== id))}
        onRejectIdentity={(id) => setIdentityReviews((prev) => prev.filter((r) => r.id !== id))}
        onApprovePhoto={(id) => setPhotoReviews((prev) => prev.filter((r) => r.id !== id))}
        onRejectPhoto={(id) => setPhotoReviews((prev) => prev.filter((r) => r.id !== id))}
        onResolveReport={(id) => setUserReports((prev) => prev.filter((r) => r.id !== id))}
      />
    );
  }

  return (
    <div>
      <div className="rounded-lg p-4 mb-5 flex items-center justify-between" style={{ background: "#20291F" }}>
        <div>
          <div className="flex items-baseline gap-1.5">
            <Wordmark size="text-2xl" />
            <span className="amr-display text-2xl leading-none" style={{ color: "#F2E9D8" }}>ADMIN</span>
          </div>
          <div className="text-xs mt-1" style={{ color: "#CBBFA0" }}>Dashboard</div>
        </div>
        <button
          onClick={onExit}
          className="text-xs font-semibold px-3 py-1.5 rounded-md shrink-0"
          style={{ background: "#F2E9D8", color: "#20291F" }}
        >
          Exit
        </button>
      </div>

      <div className="flex flex-col gap-3">
        {stats.map((stat) => (
          <button
            key={stat.key}
            onClick={() => setDrilldown(stat.key)}
            className="amr-panel rounded-lg p-4 flex items-center justify-between text-left w-full"
            style={{ borderLeft: `4px solid ${stat.accent}` }}
          >
            <span className="text-sm font-medium">{stat.emoji} {stat.label}</span>
            <span className="amr-display text-2xl" style={{ color: stat.accent }}>{stat.value}</span>
          </button>
        ))}
      </div>

      <p className="text-xs text-center mt-5" style={{ color: "#6B6459" }}>
        Tap a stat to view the cases behind it.
      </p>
    </div>
  );
}

function MessagesDrilldown({ feedbackMessages, onSendReply }) {
  const [draft, setDraft] = useState("");

  function submit() {
    const text = draft.trim();
    if (!text) return;
    onSendReply(text);
    setDraft("");
  }

  return (
    <div>
      <div className="flex flex-col gap-3 mb-4">
        {feedbackMessages.length === 0 && (
          <p className="text-sm italic" style={{ color: "#6B6459" }}>
            No messages yet — founding members can message Amari with feedback from their Profile tab.
          </p>
        )}
        {feedbackMessages.map((m, i) => (
          <div
            key={i}
            className="amr-panel rounded-lg p-3.5"
            style={{ borderLeft: `4px solid ${m.sender === "you" ? "#2F6E62" : "#E2572B"}` }}
          >
            <div className="flex items-center justify-between mb-1">
              <span className="font-semibold text-sm">{m.sender === "you" ? "Member" : "Amari"}</span>
              <span className="text-xs" style={{ color: "#6B6459" }}>{m.timeLabel}</span>
            </div>
            <p className="text-sm">{m.text}</p>
          </div>
        ))}
      </div>

      {feedbackMessages.length > 0 && (
        <div className="flex gap-2">
          <input
            type="text"
            value={draft}
            onChange={(e) => setDraft(e.target.value)}
            onKeyDown={(e) => e.key === "Enter" && submit()}
            placeholder="Reply as Amari…"
            className="amr-chip flex-1 px-3 py-2.5 rounded-md text-sm"
          />
          <button
            onClick={submit}
            disabled={!draft.trim()}
            className="amr-btn-primary px-4 rounded-md flex items-center justify-center"
            aria-label="Send reply"
          >
            <Send size={16} />
          </button>
        </div>
      )}
    </div>
  );
}

function AdminDrilldownScreen({
  category, onBack, identityReviews, photoReviews, userReports, activeCasesSample, reunitedTodayList, feedbackMessages,
  onApproveIdentity, onRejectIdentity, onApprovePhoto, onRejectPhoto, onResolveReport, onSendReply,
}) {
  const [openedItem, setOpenedItem] = useState(null); // the specific item tapped, or null for the list view

  if (openedItem) {
    return (
      <AdminItemDetailScreen
        category={category}
        item={openedItem}
        onBack={() => setOpenedItem(null)}
        onApproveIdentity={(id) => { onApproveIdentity(id); setOpenedItem(null); }}
        onRejectIdentity={(id) => { onRejectIdentity(id); setOpenedItem(null); }}
        onApprovePhoto={(id) => { onApprovePhoto(id); setOpenedItem(null); }}
        onRejectPhoto={(id) => { onRejectPhoto(id); setOpenedItem(null); }}
        onResolveReport={(id) => { onResolveReport(id); setOpenedItem(null); }}
      />
    );
  }

  return (
    <div>
      <ScreenHeader title={ADMIN_CATEGORY_TITLES[category]} onBack={onBack} />

      {category === "activeCases" && (
        <>
          <p className="text-xs mb-4" style={{ color: "#6B6459" }}>
            Showing a sample of {activeCasesSample.length} of 142 active cases.
          </p>
          <div className="flex flex-col gap-3">
            {activeCasesSample.map((c) => (
              <button key={c.id} onClick={() => setOpenedItem(c)} className="amr-panel rounded-lg p-3.5 text-left w-full">
                <div className="flex items-center justify-between mb-1">
                  <span className="font-semibold text-sm">{c.petName}</span>
                  <span className="text-xs font-semibold" style={{ color: "#2F6E62" }}>ACTIVE</span>
                </div>
                <div className="text-xs" style={{ color: "#6B6459" }}>
                  {c.species} · owner {c.ownerName} · last seen {c.lastSeenLabel} · {c.radiusKm} km radius
                </div>
              </button>
            ))}
          </div>
        </>
      )}

      {category === "idReviews" && (
        <div className="flex flex-col gap-3">
          {identityReviews.length === 0 && (
            <p className="text-sm italic" style={{ color: "#6B6459" }}>All caught up — no pending reviews.</p>
          )}
          {identityReviews.map((r) => (
            <div key={r.id} className="amr-panel rounded-lg p-3.5">
              <button onClick={() => setOpenedItem(r)} className="text-left w-full mb-3">
                <div className="flex items-center justify-between mb-1">
                  <span className="font-semibold text-sm">{r.applicantName}</span>
                  <span className="text-xs" style={{ color: "#6B6459" }}>{r.submittedLabel}</span>
                </div>
                <div className="text-xs" style={{ color: "#6B6459" }}>{r.idType}</div>
              </button>
              <div className="flex gap-2">
                <button onClick={() => onApproveIdentity(r.id)} className="amr-btn-teal flex-1 py-1.5 rounded-md text-xs">
                  Approve
                </button>
                <button onClick={() => onRejectIdentity(r.id)} className="amr-btn-secondary flex-1 py-1.5 rounded-md text-xs">
                  Reject
                </button>
              </div>
            </div>
          ))}
        </div>
      )}

      {category === "photoReviews" && (
        <div className="flex flex-col gap-3">
          {photoReviews.length === 0 && (
            <p className="text-sm italic" style={{ color: "#6B6459" }}>All caught up — no pending reviews.</p>
          )}
          {photoReviews.map((r) => (
            <div key={r.id} className="amr-panel rounded-lg p-3.5">
              <button onClick={() => setOpenedItem(r)} className="text-left w-full mb-3">
                <div className="flex items-center justify-between mb-1">
                  <span className="font-semibold text-sm">{r.petName}</span>
                  <span className="text-xs" style={{ color: "#6B6459" }}>{r.timeLabel}</span>
                </div>
                <div className="text-xs" style={{ color: "#6B6459" }}>
                  Submitted by {r.submitterName} · {r.reason}
                </div>
              </button>
              <div className="flex gap-2">
                <button onClick={() => onApprovePhoto(r.id)} className="amr-btn-teal flex-1 py-1.5 rounded-md text-xs">
                  Approve
                </button>
                <button onClick={() => onRejectPhoto(r.id)} className="amr-btn-secondary flex-1 py-1.5 rounded-md text-xs">
                  Reject
                </button>
              </div>
            </div>
          ))}
        </div>
      )}

      {category === "userReports" && (
        <div className="flex flex-col gap-3">
          {userReports.length === 0 && (
            <p className="text-sm italic" style={{ color: "#6B6459" }}>No open reports.</p>
          )}
          {userReports.map((r) => (
            <div key={r.id} className="amr-panel rounded-lg p-3.5">
              <button onClick={() => setOpenedItem(r)} className="text-left w-full mb-3">
                <div className="flex items-center justify-between mb-1">
                  <span className="font-semibold text-sm">{r.reportedUser}</span>
                  <span className="text-xs" style={{ color: "#6B6459" }}>{r.timeLabel}</span>
                </div>
                <div className="text-xs" style={{ color: "#6B6459" }}>
                  Reported by {r.reportedBy} · {r.reason}
                </div>
              </button>
              <button onClick={() => onResolveReport(r.id)} className="amr-btn-primary w-full py-1.5 rounded-md text-xs">
                Resolve
              </button>
            </div>
          ))}
        </div>
      )}

      {category === "messages" && (
        <MessagesDrilldown feedbackMessages={feedbackMessages} onSendReply={onSendReply} />
      )}

      {category === "reunitedToday" && (
        <div className="flex flex-col gap-3">
          {reunitedTodayList.map((r) => (
            <button key={r.id} onClick={() => setOpenedItem(r)} className="amr-panel rounded-lg p-3.5 text-left w-full">
              <div className="flex items-center justify-between mb-1">
                <span className="font-semibold text-sm">❤️ {r.petName}</span>
                <span className="text-xs" style={{ color: "#6B6459" }}>{r.timeLabel}</span>
              </div>
              <div className="text-xs" style={{ color: "#6B6459" }}>
                Owner: {r.ownerName}{r.heroName ? ` · Hero: ${r.heroName}` : ""}
              </div>
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

// Full detail view for a single item within any admin category -- reached
// by tapping a row in the list. Field layout is category-specific since
// each mock dataset has different shape; actionable categories (identity/
// photo reviews, user reports) get the same Approve/Reject/Resolve buttons
// available inline on the list, so an admin doesn't have to go back to act.
function AdminItemDetailScreen({ category, item, onBack, onApproveIdentity, onRejectIdentity, onApprovePhoto, onRejectPhoto, onResolveReport }) {
  const titleByCategory = {
    activeCases: item.petName,
    idReviews: item.applicantName,
    photoReviews: item.petName,
    userReports: item.reportedUser,
    reunitedToday: item.petName,
  };

  const fieldsByCategory = {
    activeCases: [
      { label: "Species", value: item.species },
      { label: "Owner", value: item.ownerName },
      { label: "Last seen", value: item.lastSeenLabel },
      { label: "Alert radius", value: `${item.radiusKm} km` },
      { label: "Status", value: "ACTIVE" },
    ],
    idReviews: [
      { label: "Applicant", value: item.applicantName },
      { label: "ID type", value: item.idType },
      { label: "Submitted", value: item.submittedLabel },
    ],
    photoReviews: [
      { label: "Pet", value: item.petName },
      { label: "Submitted by", value: item.submitterName },
      { label: "Flag reason", value: item.reason },
      { label: "Submitted", value: item.timeLabel },
    ],
    userReports: [
      { label: "Reported user", value: item.reportedUser },
      { label: "Reported by", value: item.reportedBy },
      { label: "Reason", value: item.reason },
      { label: "Reported", value: item.timeLabel },
    ],
    reunitedToday: [
      { label: "Pet", value: item.petName },
      { label: "Owner", value: item.ownerName },
      { label: "Reunited", value: item.timeLabel },
      { label: "Hero", value: item.heroName || "Not credited" },
    ],
  };

  return (
    <div>
      <ScreenHeader title={titleByCategory[category]} onBack={onBack} />

      <div className="amr-panel rounded-lg p-4 mb-5">
        <div className="text-sm space-y-2">
          {fieldsByCategory[category].map((f) => (
            <div key={f.label} className="flex justify-between gap-3">
              <span style={{ color: "#6B6459" }}>{f.label}</span>
              <span className="font-medium text-right">{f.value}</span>
            </div>
          ))}
        </div>
      </div>

      {category === "idReviews" && (
        <div className="flex gap-2">
          <button onClick={() => onApproveIdentity(item.id)} className="amr-btn-teal flex-1 py-2.5 rounded-md text-sm">
            Approve
          </button>
          <button onClick={() => onRejectIdentity(item.id)} className="amr-btn-secondary flex-1 py-2.5 rounded-md text-sm">
            Reject
          </button>
        </div>
      )}
      {category === "photoReviews" && (
        <div className="flex gap-2">
          <button onClick={() => onApprovePhoto(item.id)} className="amr-btn-teal flex-1 py-2.5 rounded-md text-sm">
            Approve
          </button>
          <button onClick={() => onRejectPhoto(item.id)} className="amr-btn-secondary flex-1 py-2.5 rounded-md text-sm">
            Reject
          </button>
        </div>
      )}
      {category === "userReports" && (
        <button onClick={() => onResolveReport(item.id)} className="amr-btn-primary w-full py-2.5 rounded-md text-sm">
          Resolve
        </button>
      )}
    </div>
  );
}

// Shared wording so the one-time welcome screen and the re-readable copy on
// Profile never drift apart into two different messages.
function amariMessageText(rank) {
  return `Hi, I'm Amari — the person behind REunited.\n\nThank you for taking this first step. By joining, you're not just protecting your own pet if they ever go missing — you're becoming one of the helping eyes that brings other people's pets home too.\n\nYou're member #${rank} of our first 100, and I wanted you to hear that from me directly. Welcome to the community — it means more than you know.\n\nIf you have pets, please add them to your profile — that's what makes the alerts work for you when it matters. And if you ever have feedback, run into a problem, or just want to say something, message me directly. I read every one myself.`;
}

function FounderWelcomeScreen({ rank, onContinue }) {
  return (
    <div className="text-center pt-4">
      <div className="flex justify-center mb-4">
        <div className="w-16 h-16 rounded-full flex items-center justify-center" style={{ background: "#E2572B" }}>
          <Award size={32} color="#F2E9D8" />
        </div>
      </div>
      <div className="amr-display text-3xl leading-none mb-1">
        FOUNDING MEMBER #{rank}
      </div>
      <p className="text-xs mb-6" style={{ color: "#6B6459" }}>
        You're one of REunited's first 100 members.
      </p>

      <div className="amr-panel rounded-lg p-4 mb-6 text-left">
        {amariMessageText(rank).split("\n\n").map((para, i) => (
          <p key={i} className={i > 0 ? "mt-3" : ""} style={{ color: i === 0 ? "#20291F" : "#6B6459" }}>
            {para}
          </p>
        ))}
        <p className="mt-3 font-semibold" style={{ color: "#20291F" }}>— Amari</p>
      </div>

      <button onClick={onContinue} className="amr-btn-primary w-full py-3 rounded-md">
        Continue to REunited
      </button>
    </div>
  );
}

export default function App() {
  const [view, setView] = useState("onboarding"); // "onboarding" | "founderWelcome" | "app" | "admin"
  const [onboardingProfile, setOnboardingProfile] = useState(null); // { contact, contactMethod, fullName, address, emergencyContactName, emergencyContactPhone }
  const [signupRank, setSignupRank] = useState(null);
  // Lives here (not inside MainApp) specifically so it survives switching to
  // the Admin view, which unmounts MainApp entirely -- otherwise Admin could
  // never see messages sent while the app view was active.
  const [messagesByThread, setMessagesByThread] = useState({});

  // Admin's side of real two-way messaging with founding members. Appends to
  // the same shared state MainApp reads, so a reply sent here shows up in
  // the member's thread immediately -- no separate sync mechanism needed,
  // since both views are reading the one source of truth.
  function sendAdminReply(threadId, text) {
    const reply = { sender: "them", text, timeLabel: "just now" };
    setMessagesByThread((prev) => ({
      ...prev,
      [threadId]: [...(prev[threadId] || []), reply],
    }));
  }

  // Account deletion: MainApp unmounting on the view switch below discards
  // all of its internal state (pets, cases, sightings, etc.) automatically
  // -- what's left is clearing the App-level state that survives unmounts
  // (onboarding profile, founding-member rank, message threads), then
  // sending the person back to square one.
  function deleteAccount() {
    setOnboardingProfile(null);
    setSignupRank(null);
    setMessagesByThread({});
    setView("onboarding");
  }

  return (
    <div
      className="min-h-screen w-full flex flex-col items-center"
      style={{
        background: "#EDE3CD",
        // Safe-area-aware padding -- keeps content clear of notches, the
        // Dynamic Island, and home-indicator/gesture-nav bars on real
        // devices, while degrading gracefully to the plain 2rem/1rem
        // padding on browsers that don't support env(safe-area-inset-*)
        // (which is exactly what a Claude preview or desktop browser sees).
        paddingTop: "max(2rem, calc(env(safe-area-inset-top) + 1rem))",
        paddingBottom: "max(2rem, calc(env(safe-area-inset-bottom) + 1rem))",
        paddingLeft: "max(1rem, env(safe-area-inset-left))",
        paddingRight: "max(1rem, env(safe-area-inset-right))",
      }}
    >
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Bebas+Neue&family=Fredoka:wght@600;700&family=Work+Sans:wght@400;500;600;700&display=swap');
        .amr-root { font-family: 'Work Sans', sans-serif; color: #20291F; }
        .amr-display { font-family: 'Bebas Neue', sans-serif; letter-spacing: 0.02em; }
        .amr-panel { background: #F2E9D8; border: 2px solid #20291F; }
        .amr-btn-primary {
          background: #E2572B; color: #F2E9D8; border: 2px solid #20291F;
          font-weight: 600; transition: transform 0.08s ease;
        }
        .amr-btn-primary:active { transform: scale(0.98); }
        .amr-btn-primary:disabled { background: #CBBFA0; color: #6B6459; border-color: #CBBFA0; }
        .amr-btn-teal {
          background: #2F6E62; color: #F2E9D8; border: 2px solid #20291F; font-weight: 600;
        }
        .amr-btn-secondary {
          background: transparent; color: #20291F; border: 2px solid #20291F; font-weight: 600;
        }
        .amr-chip {
          border: 2px solid #CBBFA0; background: #F2E9D8; color: #20291F; font-weight: 500;
        }
        .amr-chip-active { border-color: #20291F; background: #20291F; color: #F2E9D8; }
        .amr-map {
          background-color: #DDD2B6;
          background-image:
            repeating-linear-gradient(0deg, rgba(32,41,31,0.08) 0px, rgba(32,41,31,0.08) 1px, transparent 1px, transparent 34px),
            repeating-linear-gradient(90deg, rgba(32,41,31,0.08) 0px, rgba(32,41,31,0.08) 1px, transparent 1px, transparent 34px);
          cursor: crosshair;
        }
        .amr-pulse { animation: amr-pulse-anim 1.8s ease-in-out infinite; }
        @keyframes amr-pulse-anim {
          0%, 100% { box-shadow: 0 0 0 0 rgba(47,110,98,0.45); }
          50% { box-shadow: 0 0 0 8px rgba(47,110,98,0); }
        }
        .amr-fade-in { animation: amr-fade-in-anim 0.35s ease both; }
        @keyframes amr-fade-in-anim {
          from { opacity: 0; transform: translateY(4px); }
          to { opacity: 1; transform: translateY(0); }
        }
      `}</style>

      <div className="amr-root w-full max-w-sm">
        {view === "admin" ? (
          <AdminDashboardScreen
            onExit={() => setView("app")}
            feedbackMessages={messagesByThread[ADMIN_FEEDBACK_THREAD_ID] || []}
            onSendReply={(text) => sendAdminReply(ADMIN_FEEDBACK_THREAD_ID, text)}
          />
        ) : view === "app" ? (
          <MainApp
            initialProfile={onboardingProfile}
            signupRank={signupRank}
            messagesByThread={messagesByThread}
            setMessagesByThread={setMessagesByThread}
            onDeleteAccount={deleteAccount}
          />
        ) : view === "founderWelcome" ? (
          <FounderWelcomeScreen rank={signupRank} onContinue={() => setView("app")} />
        ) : (
          <Onboarding
            onComplete={(profileInfo) => {
              setOnboardingProfile(profileInfo);
              // Demo stand-in for a real signup counter: since this app has
              // no backend tracking actual global sign-ups, each run of
              // onboarding is treated as if it landed within the first 100 --
              // there's no way to simulate a "real" running count without a
              // persistent store. In a real system this would be a single
              // incrementing counter read once at account creation, not
              // randomized per session.
              setSignupRank(Math.floor(Math.random() * 100) + 1);
              setView("founderWelcome");
            }}
          />
        )}
      </div>

      {/* Staff-only entry point -- deliberately understated, since regular
          users should never notice this. In a real product this would be
          gated by an actual admin role check, not a visible link at all. */}
      {view !== "admin" && (
        <button
          onClick={() => setView("admin")}
          className="amr-root text-xs mt-4"
          style={{ color: "#A99C88" }}
        >
          Staff: Admin Dashboard
        </button>
      )}
    </div>
  );
}
